programs.sol:
"""Estimate visual padding: alignment spaces, tabs and repeated rule characters.

Ordinary prose is close to zero. Blank padding is stronger in mid-line tables
than at line starts; familiar four-column indentation is weaker. Repeated
punctuation used for rules, dotted leaders and caret underlines is positive.
Small corrections cover digits, whitespace controls, and the UTF-8 lead byte
for Latin-1 spacing/symbol characters. Word-specific variation is not modeled.
"""
READS = ()


def whitespace(text, previous):
    spaces = text.count(' ')
    tabs = text.count('\t')
    breaks = text.count('\n')
    if '\xa0' in text:
        n = spaces + text.count('\xa0')
        return min(1.6, .21 * max(0, n - 1))
    if tabs and not spaces:
        return .19 * min(3, tabs - 1) + .12 * bool(breaks and tabs > 1)
    if tabs:
        if spaces == 1:
            return -.2
        value = .125 * (spaces - 1) + .24 * (spaces >= 4)
        value += .10 * (spaces % 4 == 1) - .13 * (spaces % 4 == 3)
        return min(1.9, value)
    if breaks:
        spaces = max(map(len, text.replace('\r', '').split('\n')))
    if not spaces and breaks > 2:
        return .1 * min(6, breaks - 2)
    if spaces <= 3:
        return -.10 if spaces == 3 and not breaks else 0.0
    if breaks:
        return min(1.55, .12 * (spaces - 2))
    if previous.endswith('\n'):
        if spaces % 2:
            return min(1.2, .032 * (spaces - 4))
        return min(1.4, .07 * (spaces - 2))
    value = min(1.6, .15 * (spaces - 2.5))
    if spaces % 4 == 3:
        value -= .25
    if previous.rstrip().endswith('|'):
        value += .55
    return value


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if text.isspace():
        value = whitespace(text, previous)
        last = previous.strip()
        if len(last) >= 3 and set(last) == {'*'}:
            value += 1.0  # Gaps inside a picture made from asterisks.
        if text == '\r':
            value = .4
        elif text == '\f':
            value = 1.0
    else:
        s = text.strip()
        if s and len(set(s)) == 1:
            char, n = s[0], len(s)
            continued = previous.rstrip().endswith(char)
            if char == '.':
                if n == 1:
                    value = .25 if text.startswith(' ') else 0.0
                    if continued:
                        value = .85
                else:
                    value = .35 if n <= 4 else 1.5
                if continued and n > 1:
                    value += .5
            elif char in '-=*_~^#/\\·':
                if char in '^~' and continued:
                    value = 2.8
                elif char == '*' and n == 3:
                    value = 2.0
                elif n >= 4:
                    value = 1.7
                    if char in '*^~':
                        value = 2.3
                    elif char == '/':
                        value = 1.2
                    elif char == '·':
                        value = 2.3
                elif char == '·' and n >= 2:
                    value = 2.3
                elif char == '#':
                    value = .23 if n == 1 else .08
                elif char == '-' and n >= 2:
                    value = .3
        if text.isdigit():
            value = -.02
        b = prefix.token_bytes[-1]
        if b == b'\xc2':
            value = 1.2  # UTF-8 lead for Latin-1 controls and spacing symbols.
    return (doc, text), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 1986: a weak feature that is mostly set by the
first token of each document. It also spikes on the " b" of a git diff header.

- Document start (first token of a row, or the first token after <|endoftext|>): nothing
  precedes the token, so the value depends only on the token's kind. A markdown heading
  mark ("#", "##") or a lone capital letter gives a clear positive value; other one-character
  tokens a smaller one; capitalised words a moderate one; plain lowercase words and spaced
  words little; and the chat marker <|im_start|> a small negative.
- Git diff header: the " b" in "+++ b/path" is strongly positive.
- Everywhere else the component is near zero; its small mid-document noise is not modelled.
"""

READS = ()


def _start_value(token: str) -> float:
    core = token.lstrip(" ")
    if token == "<|im_start|>":
        return -0.17
    if not core.strip():
        return 0.1
    if token in ("#", "##"):
        return 0.8
    if token == core and len(core) == 1:
        return 0.6 if core.isupper() else 0.2
    if token.startswith(" "):
        return 0.05
    if core[0].isupper():
        return 0.26
    if core[0].isalpha():
        return 0.13
    return 0.2


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return carry, _start_value(token)
    if token == " b" and prefix.token_strings[t - 1].strip() == "+++":
        return carry, 2.0
    return carry, 0.0

programs.sol:
"""Recognize force-family spellings and short r-to-c spelling continuations.

Force/enforce/coerce and several Romance or Japanese force spellings give large
negative responses, including split spellings and suffixes. An attached c/ç
syllable after r is also negative, especially following o/u. Isolated capital C after a number or degree sign is positive.
Foreclose and encourage spellings, selected suffixes and following 'of'
get additional corrections. The previous token and a 12-character text tail
are retained, resetting at document boundaries. These coarse spelling classes
approximate the response rather than capturing all contextual variation.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = '', ''
    if carry is not None and carry[0] == doc:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    lower = token.lower()
    word = lower.strip()
    joined = (tail + token).lower()
    value = 0.0

    if 'forc' in lower:
        if 'ment' in lower:
            value = -3.2
        elif word in ('force', 'forces'):
            value = -3.1 if token[:1].isspace() else -6.7
        else:
            value = -5.2
    elif 'coerc' in lower:
        value = -5.4
    elif ('coerc' in joined and 'coerc' not in tail.lower()
          and not token[:1].isspace()):
        value = -8.5
    elif ('forc' in joined and 'forc' not in tail.lower()
          and not token[:1].isspace()):
        value = -7.0
    elif re.search(r'forz|fuerz|forç', joined) and re.search('[zç]', lower):
        value = -7.4
    elif (tail + token).endswith('フォース'):
        value = -6.5
    elif previous.endswith('強') and token.startswith('制'):
        value = -8.5
    elif word == 'of' and 'forc' in previous.lower():
        value = -1.9
    elif ('forc' in tail.lower() and not token[:1].isspace()
          and word in ('able', 'ability')):
        value = -4.5
    elif joined.endswith(('foreclosed', 'foreclosure')) and 'clos' in lower:
        value = -5.5
    elif (re.search('[rр]$', previous.lower())
          and re.match('[cçzсц]', lower)
          and not lower.startswith(('ch', 'cr'))):
        rounded = bool(re.search('[ou]r$', previous.lower()))
        short = len(token) <= 3 or lower.startswith('cation')
        if lower[0] in 'cç':
            if rounded:
                value = -4.9 if short else -1.7
            else:
                value = -0.9 if short else 0.0
        elif short:
            value = -1.1 if rounded else -0.3
    elif token.strip() == 'C':
        value = 1.1 if previous[-1:].isdigit() or '°' in previous else 0.02
    elif '°C' in token:
        value = 1.7
    elif 'courag' in lower and ('encour' in lower or 'discour' in lower):
        value = -0.8

    return (doc, token, (tail + token)[-12:]), value

programs.haiku:
"""Layer 1 MLP down-projection, feature 1987: a negative "force" detector.

It goes strongly negative on the token that completes the word "force" or one of
its relatives (force, forced, forces, enforce, enforcement, reinforce, workforce),
and on the "c" that completes "bifurcation". It is most negative for the verb forms
(forced, enforce), less for the noun "force". It is weakly positive on a capital
"C" used as a unit or label right after a number (37 C, Figure 3C).
"""

READS = ()

KEYS = ("forc", "furc")          # spelling stems that trigger it
VERB_FORMS = ("forced", "enforce", "enforced", "enforcing", "forcing")


def _word(prefix):
    """Letters of the word ending at the newest token (lower-cased), and the part the newest token supplies."""
    strings, docs = prefix.token_strings, prefix.document_ids
    last = len(strings) - 1
    word, newest = "", ""
    for i in range(last, -1, -1):
        if docs[i] != docs[last]:
            break
        s = strings[i]
        tail = ""
        for ch in reversed(s):
            if not ch.isalpha():
                break
            tail = ch + tail
        if i == last:
            newest = tail
        word = tail + word
        if len(tail) < len(s):
            break
    return word.lower(), newest.lower()


def step(carry, prefix, upstream):
    word, newest = _word(prefix)
    before = word[: len(word) - len(newest)]
    value = 0.0
    for key in KEYS:
        k = word.rfind(key)
        if k >= 0 and k + len(key) > len(before):    # the newest token completes the stem
            value = -5.5 if word in VERB_FORMS else -3.5
            break
    if value == 0.0 and prefix.token_strings[-1] in ("C", " C") and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2][-1:].isdigit() or prefix.token_strings[-2][-1:] == "°":
            value = 1.5
    return carry, float(value)

programs.sol:
"""Estimate a multilingual finite-copula / predicate signal.

English forms of 'be' get pulses determined by the preceding subject:
pronoun class, nearby determiners, and WordNet noun properties. Non-finite
auxiliaries have small negative values. Apostrophe-s gets a large pulse
in 'it's'/'that's', not ordinary possessives. Other European copulas are
gated by the language whose word-frequency dictionary best fits the recent
text. Initial inflected English verbs get a separate approximate pulse.
Most other tokens get zero; word-specific and other start-token effects
are deliberately not reproduced.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
import wordnet

READS = ()

ENGLISH = {'is': .40, 'are': .41, 'was': .35, 'were': .33, 'am': .08}
# Language-specific finite copulas. A language check avoids confusing, for
# example, Spanish "son" with an English son, or French "est" with a suffix.
COPULAS = {
    'de': {'ist': 1.8, 'sind': 1.65, 'war': 1.4, 'waren': 1.3},
    'fr': {'est': 1.7, 'sont': 1.15, 'suis': .6, 'sommes': .7},
    'es': {'es': 1.7, 'son': 1.6, 'soy': .6, 'eres': .6,
           'somos': .8, 'fue': 1.0, 'fueron': 1.0, 'era': 1.0},
    'pt': {'é': 2.0, 'são': 1.5, 'foi': 1.0, 'era': 1.0},
    'it': {'è': 1.85, 'sono': .8, 'era': 1.0},
    'ro': {'este': 2.7, 'sunt': 1.8},
    'pl': {'jest': 1.0},
    'sh': {'je': 2.0},
    'cs': {'je': 2.0},
    'da': {'er': 1.9},
    'nb': {'er': 1.9},
    'sv': {'är': 1.7},
}
FOREIGN = set().union(*(forms.keys() for forms in COPULAS.values()))
LANGUAGES = tuple(COPULAS) + ('en', 'hu', 'nl')


@lru_cache(maxsize=8192)
def language(text):
    words = re.findall(r"[^\W\d_]+", text.lower())[-10:]
    if not words:
        return 'en'
    return max(LANGUAGES, key=lambda lang: sum(
        min(6., zipf_frequency(word, lang)) for word in words))


SUBJECTS = set(('it this that he she they we you i there here '
                'which who what these those and as but').split())
DETERMINERS = {'this': .51, 'these': .36, 'the': .26, 'my': .34,
               'our': .29, 'your': .19, 'its': .22, 'a': .06, 'an': .06}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    text = '' if reset else carry[2]
    if previous in {'<|endoftext|>', '<|im_start|>'}:
        previous, text = '', ''
    p = previous.strip().lower()
    w = s.strip().lower()
    value = 0.
    if w in ENGLISH:
        attached = (not s.startswith(' ') and previous
                    and (previous[-1:].isalpha()
                         or previous.endswith(('.', '_'))))
        if attached:
            value = {'is': -.2, 'are': -.5}.get(s, 0.)
        elif not previous:
            value = .03
        else:
            value = ENGLISH[w]
            words = re.findall(r"[^\W\d_]+", text.lower())
            last = words[-1] if words else ''
            if p not in SUBJECTS:
                tags = wordnet.parts_of_speech(last)
                categories = wordnet.categories(last)
                value += .11 * ('noun' in tags) - .06 * ('adjective' in tags)
                value -= .10 * ('adverb' in tags)
                value += .09 * ('noun.cognition' in categories)
                value += .05 * ('noun.communication' in categories)
                value += .05 * ('noun.act' in categories)
                value -= .07 * ('noun.quantity' in categories)
                value += .008 * min(15, len(last))
                value += .08 * previous.startswith(' ')
                value -= .08 * previous.strip()[:1].isupper()
                value -= .13 * (not p.isalpha())
                near = set(words[-4:-1])
                value += sum(bonus for word, bonus in DETERMINERS.items()
                             if word in near)
            if s.strip() != w and not previous.strip()[:1].isupper():
                value = .30 if w != 'am' else 0.
            if p == 'it':
                value = .85 if w == 'is' else .73
            elif p == 'this':
                value = 1.08 if w == 'is' else .78
            elif p == 'that':
                value = .60 if w == 'is' else .65
            elif p in {'he', 'she'}:
                value = .28
            elif p == 'they':
                value = .30 if w == 'are' else .16
            elif p == 'we':
                value = -.25
            elif p == 'you':
                value = -.05
            elif p == 'i':
                value = .48 if w == 'am' else -.25
            elif p == 'there':
                value = .24 if w in {'is', 'was'} else .10
            elif p in {'and', 'as', 'but'}:
                value = .28
            elif p in {'which', 'what', 'who'}:
                value = .70
            elif p in {'these', 'those'}:
                value = .82
            elif p == 'here':
                noun_before = (len(words) > 1 and
                               'noun' in wordnet.parts_of_speech(words[-2]))
                value = 1.2 if noun_before else .65
            elif p in {'not', 'non'}:
                value = -.15
            if w in {'is', 'was', 'am'} and language(text) == 'hu':
                value = -.15
            elif w in {'was', 'am'} and language(text) == 'de':
                value = -.10
    elif s in {"'s", '’s'}:
        value = {'it': .86, 'that': .63, 'what': .40,
                 'there': .34, 'here': .12, 'who': .6}.get(p, -.015)
    elif s in {"'m", '’m'}:
        value = -.25
    elif s in {"'re", '’re'}:
        value = -.1 if p == 'we' else .01
    elif s in {' have', ' has'}:
        value = -.045
    elif s == ' be':
        value = -.14
    elif s == ' been':
        value = -.17
    elif s == ' being':
        value = .30 if p in {'is', 'are', 'was', 'were'} else -.10
    elif s in {'.is', '.are'}:
        value = -.4
    elif s in {"'est", '’est'}:
        value = 1.3
    elif w in FOREIGN and (s.startswith(' ') or not previous[-1:].isalpha()):
        lang = language(text)
        value = COPULAS.get(lang, {}).get(w, 0.)
    elif w == 'это':
        value = 1.0 if s.strip()[:1].isupper() else .6
    if not previous and w not in ENGLISH and w.isascii():
        if 'verb' in wordnet.parts_of_speech(w):
            bases = wordnet.base_forms(w)
            inflected = any(base != w for base in bases)
            if inflected and not w.endswith(('s', 'ing')):
                value = 2.5
            elif w.endswith('ing'):
                value = .8
    return (doc, s, (text + s)[-180:]), value

"""Approximate a negative response to clause-internal discourse modifiers.

Words such as 'also', 'then', and 'however' respond most strongly just after
pronouns or auxiliaries near the beginning of a sentence. It generally
weakens clause-initial and coordinated uses. Sentence fragments and case
provide simple grammatical cues, not a full parse. Parenthetical commas can continue
the response. Other languages' linking particles receive simpler estimates.
"""
import re

READS = ()

ADVERBS = {}
for words, magnitude in [
    ('then however', 7.9), ('therefore', 8.8), ('thus', 5.1),
    ('also', 4.1), ('now', 4.2), ('here thereby', 3.4), ('even', 3.1),
    ('though', 1.35), ('instead especially particularly', 2.0),
    ('further indeed', 1.5), ('again recently too', 1.0),
    ('subsequently', 2.4), ('meanwhile', 3.1),
]:
    ADVERBS.update(dict.fromkeys(words.split(), magnitude))

# Additive, contrastive and inferential particles in several languages.
FOREIGN = {}
for words, magnitude in [
    ('aber', 7.1), ('jedoch però', 8.5), ('же daher', 3.5),
    ('också også nämlich', 4.5), ('donc quindi ensuite jednak', 4.0),
    ('infatti invece', 4.0), ('nun également dann poi', 2.5),
    ('allerdings notamment', 3.0), ('dabei ook também', 2.0),
    ('aussi auch anche также même ainsi ici', 1.5),
]:
    FOREIGN.update(dict.fromkeys(words.split(), magnitude))
CHINESE = {'也': .8, '又': 1., '还': .9, '還': .6, '却': 1.1,
           '卻': 1.3, '则': 1.7, '則': 1.6, '再': .4, '呢': .8}
PHRASES = {'for example': 3.4, 'for instance': 3.7, 'of course': 2.7,
           'in turn': 4.4, 'in particular': 2.2, 'in effect': .5,
           'on the other hand': 9.7}
PHRASE_ENDS = {p.split()[-1]: p for p in PHRASES}
COMMA_GAIN = {'however': 1.1, 'then': .75, 'therefore': .65,
              'though': 3.4, 'meanwhile': 2.6, 'of course': 1.4,
              'for example': .65, 'in turn': .85, 'in particular': 1.4,
              'on the other hand': .3, 'in effect': .35}

AUX = set('is are was were am be been being has have had can could may '
          'might must shall should will would do does did'.split())
PRON = set('i you he she it we they me us him her them '
           'this these those'.split())
CONJ = set('and or but nor yet so if because although though since '
           'unless while whereas'.split())
PREP = set('to of at in on for by with from as than into about '
           'through before after until over under near'.split())
REL = set('which who that where when whose whom'.split())
DET = set('a an the this these those my your his her our their '
          'its any some each every no'.split())
LINKERS = {'then', 'thus', 'therefore', 'however', 'meanwhile'}


def fade(n):
    return 1. if n <= 2 else .8 if n <= 5 else .55 if n <= 8 else .35


def modifier(word, before):
    low = word.lower()
    initial = .2 if low in LINKERS else 0.
    if word[0].isupper() or before.rstrip(' \t').endswith(('\n', '\r')):
        return initial
    comma = before.rstrip().endswith(',')
    if low in {'however', 'though', 'therefore', 'meanwhile'}:
        before = before.rstrip().rstrip(',')
    elif low == 'then' and comma:
        clause = re.split(r'[;:.!?\n]', before.rstrip().rstrip(','))[-1]
        cw = clause.split()
        if cw and len(cw) <= 5 and cw[0].lower() in PRON | DET:
            before = before.rstrip().rstrip(',')
    before = before.rstrip()
    words = re.findall(r'[A-Za-z]+', before)
    if not words:
        return initial
    p = words[-1].lower()
    pp = words[-2].lower() if len(words) > 1 else ''
    blocked = p in CONJ | PREP | REL | DET and p not in PRON
    if comma and low in {'however', 'though', 'therefore', 'meanwhile'}:
        blocked = p in {'and', 'or', 'but'}
    if not before[-1].isalnum() or blocked:
        return initial
    sentence = re.split(r'[;:.!?\n]', before)[-1].split()
    n = len(sentence)
    if words[-1][0].isupper() and p in PRON:
        n = 1
    elif len(words) > 1 and words[-2][0].isupper() and pp in PRON:
        n = 2 if p in AUX else n
    aux, subject = p in AUX, p in PRON
    subject_aux = aux and pp in PRON
    f = fade(n) * (1.15 if subject or subject_aux else .9)
    if p in {'right', 'just', 'very', 'once'}:
        f *= .05
    if p in {'see', 'click', 'tap'}:
        f *= .25 if low == 'also' else .05
    if low == 'then':
        if p in {'even', 'only', 'true', 'false'} or sentence[-1][0].isdigit():
            return initial
        if n > 5 and not aux:
            f *= .2
        if any(w.lower() in CONJ for w in words[-5:]):
            f *= .6
    elif low == 'now' and not subject:
        f *= .7 if aux and not subject_aux else 1.
        if not aux:
            nominal = pp in DET or words[-1][0].isupper()
            f *= .55 if n <= 5 and nominal else .18
    elif low == 'here':
        nominal = pp in DET or (n <= 5 and sentence[0].lower() in DET
                  and not any(w.lower() in AUX for w in words[-n:]))
        f *= 1.15 if nominal else .4
    elif low == 'even' and not subject and not subject_aux:
        if aux:
            f *= .1 if p in {'is', 'am', 'be'} else .6
        elif p == 'not' or before.endswith(("n't", 'n’t')):
            f *= .5
        else:
            return .18
    return -ADVERBS[low] * f


def phrase_factor(phrase, text):
    if text[-len(phrase)][0].isupper():
        return .45 if phrase == 'in turn' else .03
    before = text[:-len(phrase)]
    if not before.strip() or before.rstrip(' \t').endswith(('\n', '\r')):
        return .03
    before = before.rstrip().rstrip(',')
    words = re.findall(r'[A-Za-z]+', before.lower())
    if not words:
        return .1
    if phrase == 'in turn' and words[-1] in PRON | REL | AUX:
        return 1.
    n = len(re.split(r'[;:.!?\n]', before)[-1].split())
    return fade(n) * (.25 if words[-1] in CONJ | PREP | REL else 1.)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.)
    _, old, comma = carry
    token = prefix.token_strings[-1]
    text = old + token
    value, following_comma = -.004, 0.
    label = None
    if token == ',':
        value += comma
    elif token.strip() in CHINESE:
        value -= CHINESE[token.strip()]
    else:
        match = re.search(r'(?<![^\W\d_])([^\W\d_]+)\Z', text)
        if match:
            word, before = match[1].lower(), text[:match.start()]
            phrase = PHRASE_ENDS.get(word)
            if phrase and text.lower().endswith(phrase):
                value -= PHRASES[phrase] * phrase_factor(phrase, text)
                label = phrase
            elif word in FOREIGN:
                internal = (before.rstrip() and before.rstrip()[-1].isalnum()
                            and not match[1][0].isupper()
                            and not before.rstrip(' \t').endswith(('\n', '\r')))
                value -= FOREIGN[word] * (1. if internal else .2)
            elif word in ADVERBS:
                value += modifier(match[1], before)
                label = word
            if label in COMMA_GAIN or label in PHRASES:
                following_comma = value * COMMA_GAIN.get(label, 1.)
    return (doc, text[-200:], following_comma), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:1990: a mid-clause connective detector.

It goes negative on discourse connectives and adverbs such as however, therefore, also, then,
now, thus, here, and their German, French, Italian, Russian, Chinese and other equivalents
(aber, donc, jedoch, også, ...). It is active only when the word sits inside a clause, after a
subject, auxiliary or modal and before the main verb: "They have also been", "The burden then
shifts", "This process, however, has". It stays silent when the word opens a sentence or
follows a conjunction or punctuation: "And then", "But now", "; however", "...then the".

Strength: however, therefore and aber are strongest, also and then medium, here, again and too
weak. Scaling: stronger right after a subject or modal and early in a clause, weaker late in a
long clause; "then" inside an "if ... then" conditional stays silent. The comma closing an
interrupting ", however," is negative too, and commas after "for example" or "of course" are
mildly negative. Everywhere else the prediction is 0.
"""

READS = ()

# Strength of each connective when it is active (activation is -strength).
CONNECTIVES = {
    "however": 4.5, "therefore": 5.5, "though": 0.9, "thus": 3.0, "indeed": 2.0,
    "also": 2.8, "then": 3.6, "now": 1.7, "here": 1.0, "again": 0.5, "too": 0.5,
    "instead": 0.7, "further": 0.6,
    "aber": 6.5, "donc": 5.0, "jedoch": 9.0, "nämlich": 5.0, "quindi": 5.0, "ensuite": 5.0,
    "però": 9.0, "jednak": 4.0, "же": 3.0, "также": 1.5, "nun": 2.9, "auch": 1.5,
    "aussi": 1.9, "anche": 1.2, "dann": 2.2, "alors": 1.6, "ainsi": 1.8, "hereby": 2.5,
    "dabei": 2.7, "也": 1.0, "还": 1.0, "又": 1.0, "却": 1.0, "また": 0.3,
    "også": 4.0, "daher": 3.0, "poi": 2.6, "meanwhile": 2.5, "entonces": 1.4, "subsequently": 1.3,
    "furthermore": 1.1, "likewise": 1.1, "también": 0.9, "тоже": 0.9, "además": 0.8,
}
# Words that, just before the connective, make it open or sit at the start of a clause.
CLOSED_BEFORE = {
    "", ",", ".", ";", ":", "!", "?", "\n", "and", "but", "or", "so", "And", "But", "Or", "So",
    ")", "$", '"', "'", "]", "}", "right", "for", "since", "until", "by", "even",
}
# Connectives that interrupt a clause when set off by commas ("This process, however, has").
INTERRUPTERS = {"however", "therefore", "though"}
# Words after which a following comma is a mild parenthetical comma ("for example,").
PARENTHETICAL = {"example", "course", "fact", "particular", "instance", "hand", "contrast",
                 "contrary", "indeed", "too", "then", "thus"}
# Words that come right before a verb slot: a subject, an auxiliary or a modal.
VERB_SLOT = {
    "can", "may", "will", "should", "must", "could", "would", "might", "shall", "have", "has",
    "had", "is", "are", "was", "were", "be", "been", "being", "am", "He", "She", "It", "We",
    "They", "I", "You", "he", "she", "it", "we", "they", "you",
}
CONDITIONAL = {"if", "when", "whether", "unless"}
SENTENCE_END = {".", "!", "?", "\n", "\n\n", "<|endoftext|>", "<|im_end|>"}


def _word(token):
    return token.strip()


def _clause_length(toks, t):
    """Tokens since the last sentence end, before position t."""
    n = 0
    while n < t and _word(toks[t - 1 - n]) not in SENTENCE_END:
        n += 1
    return n


def _in_conditional(toks, t):
    """Whether an 'if'/'when' opens the current sentence before position t."""
    for i in range(t - 1, max(-1, t - 40), -1):
        w = _word(toks[i])
        if w in SENTENCE_END:
            return False
        if w in CONDITIONAL:
            return True
    return False


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    w = _word(toks[t])
    new_doc = t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]
    prev = "\n" if new_doc else _word(toks[t - 1])
    value = 0.0
    if w in CONNECTIVES:
        if w in INTERRUPTERS and prev == ",":
            value = -CONNECTIVES[w]
        elif prev not in CLOSED_BEFORE and not (w == "then" and _in_conditional(toks, t)):
            scale = 1.3 if prev in VERB_SLOT else 0.8
            scale *= 1.3 if _clause_length(toks, t) <= 5 else 0.8
            value = -CONNECTIVES[w] * scale
    elif w == "," and prev in INTERRUPTERS and t >= 2 and _word(toks[t - 2]) == ",":
        value = -5.0
    elif w == "," and prev in PARENTHETICAL:
        value = -1.0
    return carry, float(value)

programs.sol:
"""A sparse spelling rule, not a general semantic classifier.

Strong positive responses mark dot-prefixed NET and selected Han spellings
for peace, quiet, cleanliness, freezing and stopping. Multi-character Han
words are weaker. Smaller rules cover 'ning', dot-config/GitHub names and
Chinese references to 'this website'. Everything else is zero. Split UTF-8
characters are recognized on completion; state resets between documents.
These rules approximate observed positive bursts, leaving other bursts and
fine context dependence unmodeled.
"""
READS = ()


def han_value(word):
    strength = 0.0
    if word in ('宁', '寧'):
        strength = 5.8
    elif any(ch in word for ch in '净淨凈浄'):
        strength = 4.1
    elif any(ch in word for ch in '静靜'):
        strength = 3.8
    elif word in ('凝', '凌'):
        strength = 3.8
    elif word == '停':
        strength = 3.0
    elif word in ('冷', '洁', '潔'):
        strength = 1.0
    if strength:
        value = strength / len(word)
        if len(word) > 1 and word[0] in '静靜':
            value *= 0.4
        return value
    return 1.8 if word.endswith(('本站', '本网')) else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', b'') if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', 'replace')
    completed = (tail + raw).decode('utf-8', 'replace')
    word = token if '\ufffd' not in token else completed[-1:]
    value = han_value(word)

    if token in ('.NET', '.Net', '.net'):
        value = 8.0 if token == '.NET' else 4.0
        if previous.lower().endswith('asp'):
            value = 10.5
    elif token.strip().lower() == 'net':
        value = 0.35
        if not token[0].isspace() and (previous.endswith('.') or
                                      previous.lower().endswith('dot')):
            value = 7.5
    elif token.lower() in ('-net', '_net', '/net'):
        value = 1.6
    elif token.strip().lower() == 'ning':
        value = 3.8 if token.strip().startswith('N') else 2.0
    elif token == '.github':
        value = 0.7
    elif token == '.config' or (token == 'config' and previous.endswith('.')):
        value = 0.9

    return (doc, (previous + token)[-32:], (tail + raw)[-3:]), value

"""Approximate a detector of text-encoded code layout.

Spaces after printed backslash-n are the main negative trigger, strengthened
by nearby code punctuation. Printed newline/tab escapes and backticks also
respond. Spaced/repeated backticks flag contexts where nonbreaking spaces
respond strongly. Actual newline indentation normally gets zero. Keep a short
text suffix, reset between documents, and use conservatively scaled amplitudes.
Word-specific and document-opening responses are deliberately omitted.
"""
import re

READS = ()

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    s = prefix.token_strings[-1]
    punctuation = min(3, sum(c in '{}();=[]' for c in tail[-64:]))
    escaped_indent = re.search(r'\\n( *)$', tail)
    escaped_tabs = re.search(r'\\[nt](?:\\t)*$', tail)
    real_indent = re.search(r'\n[ \t]*$', tail)
    broken_markup = '` `' in tail or tail.count('``') >= 2
    value = 0.0

    if s and set(s) == {' '}:
        n = len(s)
        if escaped_indent:
            if escaped_indent[1]:
                value = -0.1  # Further pieces of an already-read space run.
            elif n == 1:
                value = -1.5 - 0.3 * punctuation
            elif n == 2:
                value = -2.2
            elif n < 32:
                value = -3.5 - 0.35 * punctuation
                if n >= 8:
                    value += 0.2
            else:
                value = -1.0
        elif tail and not real_indent and n > 1:
            value = -0.2
    elif s and all(c in ' \xa0' for c in s) and '\xa0' in s:
        if broken_markup:
            value = -1.2 if s.count('\xa0') == 1 else -2.8
            if previous.isspace() and s.count('\xa0') > 1:
                value = -1.0
        elif previous.isspace() and s.count('\xa0') > 1:
            value = -0.3
    elif s == '\\t':
        value = -1.45 if escaped_indent else -0.55 if escaped_tabs else 0.0
    elif s == '\\n':
        value = -0.4 - 0.22 * punctuation
    elif s == 'n' and tail.endswith('\\'):
        before_slash = tail[-2:-1]
        value = -0.9 if before_slash and before_slash in ');}]' else -0.4
        if before_slash == '\\':
            value = -0.1
        elif before_slash == ' ' and not punctuation:
            value = 0.15
    elif s and not s.strip(' `') and '`' in s:
        value = -0.05
        if broken_markup and previous.strip(' `'):
            value = -0.7 if len(s.strip()) > 1 or s.startswith(' ') else -0.2
    return (doc, (tail + s)[-128:], s), 0.8 * value

programs.haiku:
"""Escaped line starts: a "broken newline" detector (layer 1, MLP output unit 1992).

Code is often pasted inside a string with its line breaks written as the two characters
backslash + n (JSON, quoted strings, escaped source), not as real newlines. The model
then never sees a line start, only the escape. This component goes negative on that
escape, and most strongly on the indentation that follows it:

  - the escape itself ("\\n", "\\t", or the letter n/t after a backslash): about -0.7
  - indentation (3+ spaces) right after an escape: about -4.2 (a single space or two: -2.2)
  - the first word of a code statement after an escape (print, console, const, ...): -1.4;
    other words and symbols: -0.4; a quote character after the escape: 0
  - a token right after that indentation: -0.4 (code words -1.2)

Two side cases: a whitespace run right after a markdown backtick is about -2.5, and a run of
middle dots "··" is a constant +2.7 (in that row the model does not use the component, so it
matters only for the activation).

Everything else predicts 0. Real newlines do not trigger it.
"""

READS = ()

CODE_WORDS = {
    "print", "console", "const", "var", "let", "function", "import", "if", "for",
    "from", "func", "def", "class", "return", "try", "except",
}
ESCAPES = ("\\n", "\\t", "\\r")


def _is_escape(prev2, prev):
    # prev is an escape: the token "\n", "\t", "\r", or a letter n/t/r right after a backslash
    if prev in ESCAPES:
        return True
    return prev in ("n", "t", "r") and prev2.endswith("\\")


def _is_blank(tok):
    return tok != "" and tok.strip(" \xa0\t") == ""


def _after_escape(tok):
    if _is_blank(tok):
        return -4.2 if len(tok) >= 3 else -2.2   # indentation vs a single space
    if tok in ESCAPES:
        return -1.0
    if tok[:1] in ("'", '"') or tok.startswith('\\"'):
        return 0.0                               # a string quote after the escape: nothing
    if tok.strip() in CODE_WORDS:
        return -1.4
    return -0.4


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[2] != doc:          # a new document resets the state
        prev, prev2, after_indent = "", "", False
    else:
        prev, prev2, after_indent = carry[0], carry[1], carry[3]
    if tok != "" and set(tok) == {"·"}:
        value = 2.7
    elif _is_escape(prev2, prev):
        value = _after_escape(tok)
    elif after_indent and not _is_blank(tok):
        value = -0.4 if tok.strip() not in CODE_WORDS else -1.2
    elif _is_blank(tok) and prev.endswith("`"):
        value = -2.5
    elif tok in ESCAPES or (tok in ("n", "t", "r") and prev.endswith("\\")):
        value = -0.7
    else:
        value = 0.0
    indent_after_escape = _is_escape(prev2, prev) and _is_blank(tok)
    return (tok, prev, doc, indent_after_escape), value

programs.sol:
"""Predict negative pulses on chat, tool, and thinking boundary tokens.

Pulse sizes approach characteristic levels as document position increases;
initial markers are weaker. Message ends are slightly positive unless they
immediately follow another boundary. Ordinary text gets a small, fading
positive background, with coarse character-class averages at document starts.
End-of-text is neutral except for a positive document-initial value. This
omits the component's remaining word-specific and contextual variation.
"""
from math import sqrt

READS = ()

# Long-context pulse, and how much it weakens near the document's beginning.
BOUNDARIES = {
    '<|im_start|>': (-4.24, 1.78),
    '<tool_call>': (-2.17, 0.43),
    '</tool_call>': (-2.75, 1.16),
    '<tool_response>': (-3.14, 1.27),
    '</tool_response>': (-3.82, 2.43),
    '<think>': (-4.03, 0.93),
    '</think>': (-1.48, 0.0),
}
INITIAL_MARKERS = {
    '<|im_start|>': -0.605,
    '<tool_call>': -0.42,
    '</tool_call>': -0.30,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
        position += 1

    value = 0.035 / (1 + position / 24)
    if position == 0:
        text = token.strip()
        if text.isalpha():
            value = -0.24
        elif not text or text.isdigit():
            value = 0.0
        else:
            value = -0.14

    if token in BOUNDARIES:
        level, early = BOUNDARIES[token]
        value = level + early / sqrt(position + 1)
        if position == 0 and token in INITIAL_MARKERS:
            value = INITIAL_MARKERS[token]
    elif token == '<|im_end|>':
        value = -0.08 if previous in BOUNDARIES else 0.35
        if position == 0:
            value = -0.15
    elif token == '<|endoftext|>':
        value = 0.60 if position == 0 else 0.0
    return (doc, position, token), value

"""A document-initial-token feature, modulated by readable token shapes.

Initial punctuation, layout and digits usually have a large positive value;
ordinary words have smaller values, estimated from length, case, English
frequency and dictionary word classes. A homogeneous initial run keeps the same
response. Once different text arrives, predict zero, apart from an observed
negative response to an initial number beginning with 12 (and its repeated 2).
The shape rules approximate, rather than memorize, individual token responses.
"""
from functools import lru_cache
import unicodedata
import regex
import wordnet
from wordfreq import zipf_frequency

READS = ()
PREPOSITIONS = set(
    'of to in on at by with for from as into about under over after before '
    'between through without within'.split()
)


@lru_cache(maxsize=8192)
def initial_value(s):
    t = s.strip()
    if s.startswith('<|'):
        return 7.7 if s == '<|endoftext|>' else -1.8
    if s == '\0':
        return 10.5
    if not t:
        if s == '\r':
            return -2.4
        if '\n' in s and not s.startswith((' ', '\t')):
            return 4.2
        if s.startswith('\t') and ' ' in s:
            return 0.3
        return max(-0.5, 2.8 - 0.075 * len(s))
    if t.isdecimal():
        if t == '0':
            return 0.2
        if t == '9':
            return -0.5
        return 2.8
    if '\ufffd' in t:
        return 2.3
    if not any(c.isalnum() for c in t):
        if set(t) <= set('#*'):
            return 6.4 if len(t) == 2 else 4.3
        if t in ('"""', "'''"):
            return 5.9 if '\n' in s else 7.6
        if t.startswith('/*'):
            return 4.6 + 1.3 * t.startswith('/**') - 0.9 * ('\n' in s)
        if s == ' .':
            return 6.7
        if t in ('.', ',', ';'):
            return 2.9 - 0.3 * ('\n' in s)
        if t in ('?', '!', ':'):
            return 1.3
        if t in ('"', "'", '“', '‘'):
            return 3.8 - 1.6 * s.startswith(' ')
        if len(t) == 1 and unicodedata.category(t) == 'Pe':
            return 3.4
        if len(t) == 1 and unicodedata.category(t) == 'Ps':
            return 3.2 if s.startswith(' ') else 2.2
        if all(c == '·' for c in t):
            return 3.3
        return 2.6 - 0.3 * min(3, len(t) - 1) - 0.3 * ('\n' in s)
    if regex.search(r'\p{Script=Han}', t):
        return 0.35 if len(t) == 1 else 0.05
    if not t.isascii():
        base = -0.9 if regex.search(r'\p{Script=Arabic}', t) else 0.3
        return base + 0.8 * (len(t) <= 2)
    if s in ('package', 'class', 'const', 'def', 'var', 'function'):
        return 3.7
    if s in ('import', 'from'):
        return 5.7 if s == 'import' else 3.5
    if s in ('\\n', '\\t'):
        return 4.9
    z = zipf_frequency(t.lower(), 'en')
    pos = wordnet.parts_of_speech(t.lower())
    return (0.33 + 0.22 * max(0, 5 - len(t))
            + 0.14 * s.startswith(' ')
            + 0.85 * (s.startswith(' ') and z >= 6.2)
            + 1.48 * (len(t) == 1 and t.islower())
            + 0.74 * (len(t) == 1 and t.isupper())
            - 0.28 * ('noun' in pos) - 0.25 * ('verb' in pos)
            - 0.16 * max(0, 4 - z)
            - 0.16 * t.istitle() - 0.16 * t.isupper()
            + 0.64 * (t.lower() in PREPOSITIONS)
            - 1.51 * (s in ('A', 'I'))
            - 0.66 * (t.istitle() and t.lower() in
                      ('the', 'this', 'that', 'these', 'those')))



def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous = None
        carry = (doc, s, 0, True, s, prefix.token_ids[-1])
    else:
        _, first, age, homogeneous, previous, first_id = carry
        # Compare token identities: different incomplete UTF-8 tokens can
        # decode to the same replacement character.
        carry = (doc, first, age + 1,
                 homogeneous and prefix.token_ids[-1] == first_id, s, first_id)
    _, first, age, homogeneous, _, _ = carry
    if homogeneous:
        value = initial_value(first)
    elif first == '1' and age == 1 and s == '2':
        value = -9.14
    elif first == '1' and age == 2 and previous == '2' and s == '2':
        value = -1.6
    else:
        value = 0.0
    return carry, value

"""A sparse, tokenization-sensitive lexical approximation.

The main positive triggers are East Asian labor and farm spellings, not a
language-independent notion of work. Isolated labor characters are strongest;
selected compounds and related Korean/Vietnamese syllables are weaker.
There are also small Cyrillic, Thai, and individual-character side responses,
plus document-initial formatting rules. Unmatched positions predict zero.

These rules capture prominent training examples without a vocabulary table.
Join incomplete UTF-8 characters, and reset that buffer at document boundaries.
"""
import codecs

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, b'', '')
    _, pending, previous = carry
    raw = prefix.token_bytes[-1]
    data = pending + raw
    piece, used = codecs.utf_8_decode(data, 'replace', False)
    word = piece.strip()
    value = 0.0

    if word in ('劳', '勞', '労'):
        value = 8.8
        if word == '勞' and previous.endswith('疲'):
            value = 3.3
        elif previous.endswith('代'):
            value = 6.6
        elif previous.endswith('帕'):
            value = 4.8
    elif word == '劳动':
        value = 8.0
    elif '劳动' in word and '劳动力' not in word:
        value = 2.2
    # Toil, diligence, and labor services.
    elif word in ('劳累', '勤劳', '劳务'):
        value = 2.7
    elif word in ('农', '農'):
        value = 6.5 if pending else 4.0
    # Farmers, farm families, rural villages, and 'three rural issues'.
    elif word in ('农民', '农家', '农村', '三农'):
        value = 1.6
    # Sino-Korean nong (agriculture), no-, and the similar ro syllable.
    elif word == '농':
        value = 5.0
    elif word in ('노', '노동'):
        value = 3.3 if raw.startswith(b' ') or pending else 2.6
    elif word == '놀':
        value = 7.3 if pending else 0.6
    elif word == '로':
        value = 0.7 if raw.startswith(b' ') else 1.4
    elif word in ('으로', '대로'):
        value = 0.7
    elif word == 'nông':
        value = 2.8
    elif word in ('ông', 'ô'):
        # Vietnamese syllables lô/lông; don't fire in French contrôle.
        if previous.endswith('l'):
            value = 3.0 if word == 'ông' else 2.0
        elif word == 'ông' and previous.endswith('h'):
            value = 1.0
        elif word == 'ông' and previous.endswith('n'):
            value = 2.8
    elif word == 'род' and (previous == 'на' or previous.endswith(' на')):
        value = 1.2  # The Russian/Ukrainian root narod-, not every rod-.
    elif word == 'อง' and previous.endswith('ื่'):
        value = -3.1  # Thai -ueang syllable ending, e.g. เรื่อง / เนื่อง.
    elif word in ('动', '動') and previous.endswith(('劳', '勞')):
        value = 8.5  # The segmented spelling of the word for labor.
    elif word == '屌':
        value = 3.2  # A separate positive response to this vulgar Han character.
    elif word == '歴':
        value = 1.4  # Japanese history character.
    elif word == '寒':
        value = 1.7  # Han character for cold.

    if value == 0.0 and first:
        if word == '<|im_start|>':
            value = -0.45
        elif word.isdecimal():
            value = 0.24
        elif piece.isspace() and used == len(data):
            value = 0.23
    if word and not word.strip('·') and not previous.strip('·'):
        value = 1.12  # A document-initial run of middle-dot padding.

    return (doc, data[used:], (previous + piece)[-12:]), value

programs.haiku:
"""Layer-1 MLP down_proj component 1995: a 'lao / ro' syllable detector.

Fires strongly on the Chinese character 劳 (láo, "labour", as in 劳动, 帕劳, 劳拉)
and moderately on the "ro" syllable in Korean (로, as in 회로, 대로) and in
Japanese/Russian (ロ, род). It is pushed negative on the Thai syllable อง (ong).
Everything else predicts 0.
"""

READS = ()

LAO = "劳"
RO_TOKENS = {"ロ", "род"}
NEGATIVE = {"อง": -3.0}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if LAO in tok:
        value = 6.0
    elif tok in RO_TOKENS or tok.endswith("로"):
        value = 1.3
    else:
        value = NEGATIVE.get(tok, 0.0)
    return None, float(value)

"""layers.1.mlp.down_proj:1996 - a turn/document-boundary detector.

Fires (positive activation) at the places where the text starts or stops:
  * the chat end-of-turn token <|im_end|>, strongly when it follows a sentence-final
    punctuation mark (the end of a finished reply), weaker when it follows a closing
    tool tag (</tool_response>, </tool_call>);
  * the first token of a new document (the token right after <|endoftext|>);
  * the first token of a row (no preceding context, the model's attention-sink position).
Everywhere else it is near zero (its typical size is ~0.05 with rare large outliers,
which this program does not try to predict).

Values are the average activation observed in training text for each case.
"""

SENTENCE_END = {".", "?", "!", "。", "？", "！"}
TOOL_CLOSE = {"</tool_response>", "</tool_call>"}

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if prefix.position == 0:
        return carry, 0.24
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.37
    if token == "<|im_end|>":
        before = prefix.token_strings[-2]
        if before in SENTENCE_END:
            return carry, 0.92
        if before in TOOL_CLOSE:
            return carry, 0.37
        return carry, 0.65
    return carry, 0.0

