"""Distinguish labeling colons from colons that introduce a continuation.

List-introducing words lower the prediction. Numerical separators,
language names and biographical fields raise it. A line break lowers it,
except for Python syntax; the effect may extend to a separate line break.
Other tokens default to zero, leaving document-initial lexical spikes
unexplained.
"""
import re
import pycountry

READS = ()
LANGUAGES = frozenset(
    getattr(language, field, '').lower()
    for language in pycountry.languages
    for field in ('name', 'common_name', 'inverted_name')
)
LIST_INTRODUCERS = {
    'are', 'were', 'include', 'includes', 'including', 'contain', 'contains',
    'comprise', 'comprises', 'comprising', 'namely', 'follows', 'following',
}
CHINESE_INTRODUCERS = ('例如', '比如', '如下', '以下', '包括', '包含', '其中')
CLAUSE_ENDINGS = {
    'is', 'was', 'be', 'say', 'says', 'said', 'read', 'reads', 'write',
    'writes', 'below', 'under', 'thus',
}
UNFINISHED_CLAUSES = {
    'as', 'to', 'for', 'by', 'at', 'with', 'that', 'which', 'when', 'because',
    'has', 'have', 'had', 'does', 'do', 'did', 'can', 'could', 'will', 'would',
    'should', 'must', 'may', 'might',
}
BIOGRAPHICAL_FIELDS = {
    'birth', 'death', 'citizenship', 'occupation', 'sport', 'team', 'party',
    'genre', 'member', 'country',
}


def colon_value(text, token):
    if '::' in token or '://' in token or re.match(r'["\']+:', token):
        return 0.0
    line = text.replace('\\n', '\n').split('\n')[-1]
    phrase = re.split(r'[.!?;:：]', line)[-1]
    words = re.findall(r'[A-Za-z]+', phrase)
    last = words[-1] if words else ''
    word = last.lower()
    newline = '\n' in token or '\\' in token or token.endswith('-')
    python = re.search(
        r'(?:^|\t|\d:)\s*(?:async\s+)?'
        r'(?:if|elif|else|for|while|def|class|try|except|finally|with|case)\b',
        line,
    )
    # Each pair is the level without a line break, then its line-break change.
    if newline and python:
        value, change = -0.07, 0.0
    elif word in LIST_INTRODUCERS or phrase.endswith(CHINESE_INTRODUCERS):
        value, change = -2.18, -0.32
    elif 'following' in [w.lower() for w in words]:
        value, change = -1.88, -0.41
    elif word in CLAUSE_ENDINGS:
        value, change = -0.80, -0.80
    elif word in UNFINISHED_CLAUSES:
        value, change = -0.29, -1.55
    else:
        value, change = 0.35, -1.21
    value += change * newline - 0.33 * min(len(words), 15) / 15
    if newline and token[:1] in ')]}' and not python:
        value += 0.50
    if '：' in token:
        value -= 0.39
    if re.search(r'\d\s*$', text):
        value += 0.40
    if re.search(r'\b(?:here|these|this)\b', phrase.lower()):
        value -= 0.76
    if word in {'example', 'examples', 'instance'}:
        value -= 0.73
    if len(last) >= 4 and last[0].isupper() and word in LANGUAGES:
        value += 1.50
    if re.search(r'\.(?:py|js|ts|c|cpp|h|go|rs|java|rb|php)\s*$', text):
        value += 0.30
    if word in BIOGRAPHICAL_FIELDS:
        value += 0.62
    if word in {'error', 'warning', 'failed', 'fail', 'default'} \
            or word.endswith('warning'):
        value += 0.45
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous, previous_value = b'', '', 0.0
    else:
        _, history, previous, previous_value = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if ':' in token or '：' in token:
        value = colon_value(history.decode('utf-8', 'replace'), token)
    elif '\n' in token and not token.strip(' \t\r\n-') \
            and previous.endswith((':', '：')):
        value = min(0.0, previous_value)
    history = (history + prefix.token_bytes[-1])[-700:]
    return (doc, history, token, value), value

"""Continuation markers in a coarse grammatical context.

Conjunctions, commas and adverbs respond negatively in infinitival/modal
or imperative contexts, differently after copulas, perfect auxiliaries
or examples. Remember the latest cue with a 10%-per-token fade; weaken it
at punctuation. Refine 'to' once the following word has arrived, using
its dictionary class; recognize possible imperatives at sentence starts.
Negation has its own fading flag. Leftover whitespace runs are positive;
line-initial bullets and numbered-list dots are mildly negative.
All other tokens receive zero. This is a heuristic, not a full parser.
"""
from functools import lru_cache
import wordnet

READS = ()

# Grammatical cue words, conjunction response, adverb response.
CUES = (
    ({'to'}, -1.92, -1.19),
    (set('can could will would shall should may might must cannot do does did'.split()),
     -1.63, -1.38),
    (set("am is are was were be been being 's 'm 're ’s ’m ’re".split()),
     0.26, 0.09),
    (set('have has had'.split()), -0.30, 0.23),
    (set('as including like'.split()), 0.50, 0.02),
    (set('while by without after before'.split()), 0.20, 0.24),
    (set('let please'.split()), -0.59, -0.38),
    ({'than'}, 0.14, -0.55),
    (set('i we you they'.split()), -0.87, -0.49),
    (set('he she it'.split()), -0.49, -0.09),
)
ADVERBS = {
    'additive': set('also further again too'.split()),
    'restrictive': set('just only merely simply'.split()),
    'temporal': set(('ever never still always already usually often '
                     'sometimes generally').split()),
    'sequential': set('then thus otherwise therefore'.split()),
    'likelihood': set(('likely probably possibly necessarily certainly '
                       'potentially apparently presumably definitely').split()),
    'degree': set(('really very quite rather highly extremely relatively '
                   'particularly especially').split()),
}
OTHER_CONJUNCTIONS = set(
    'und oder et ou y og och eller és và и или 和 与 并 或'.split())

# Baseline, context gain, negation response, case/boundary, previous digit.
RESPONSE = {
    'and': (-0.26, 1.0, -0.17, 0.17, 0.25),
    'or': (-0.13, 0.66, -0.31, 0.05, 0.1),
    'comma': (-0.01, 0.18, 0.01, -0.01, 0.03),
    'additive': (-0.02, 0.73, 0.24, 0.0, 0.0),
    'restrictive': (-0.0, 1.0, -0.66, 0.0, 0.0),
    'temporal': (-0.06, 0.93, -0.47, 0.0, 0.0),
    'sequential': (-0.13, 0.95, 0.01, 0.0, 0.0),
    'manner': (0.05, 0.65, -0.12, 0.0, 0.0),
    'likelihood': (0.19, 0.98, -0.5, 0.0, 0.0),
    'degree': (-0.04, 0.36, -0.49, 0.0, 0.0),
}


@lru_cache(maxsize=8192)
def parts(word):
    return wordnet.parts_of_speech(word) if word.isalpha() else set()


def marker(token):
    word = token.strip().lower()
    if word in {'and', 'or'}:
        return word
    if token in {',', '，', ',\n'}:
        return 'comma'
    if token.startswith(' ') or (token and token[0].isupper()):
        for name, words in ADVERBS.items():
            if word in words:
                return name
        if word.endswith('ly') and 'adverb' in parts(word):
            return 'manner'
    return None


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, mode, strength, negation = '', '', 0, 0., 0.
    else:
        _, previous, before, mode, strength, negation = carry
    word, older = previous.strip().lower(), before.strip().lower()
    strength *= .9
    negation *= .9
    # 'to the ...' is prepositional, unlike 'to build ...'.
    if older == 'to' and word.isalpha():
        allowed = {'verb', 'adverb'} & parts(word)
        exceptions = {'not', 'never', 'ever', 'just', 'also', 'still', 'even', 'only'}
        if not allowed and word not in exceptions:
            strength = 0.
    boundary = previous.startswith(' ') or (previous and previous[0].isupper())
    if boundary or word in {"'s", "'m", "'re", '’s', '’m', '’re'}:
        for i, (words, _, _) in enumerate(CUES):
            if word in words:
                mode, strength = i, 1.
                break
    start = not before or before.rstrip().endswith(('.', ':', '!', '?', '\n'))
    imperative = start and 'verb' in parts(word) and not word.endswith(('ing', 'ed'))
    if imperative and (previous == ' ' + word or previous.strip().istitle()):
        if not any(word in words for words, _, _ in CUES):
            mode, strength = 6, 1.
    if any(c in previous for c in '.!?;\n'):
        strength *= .25
    if word in {'not', "n't", "'t", '’t'}:
        negation = 1.

    kind, value = marker(token), 0.
    if kind is not None:
        baseline, gain, negative, case, digit = RESPONSE[kind]
        family = 1 if kind in {'and', 'or', 'comma'} else 2
        value = baseline + gain * CUES[mode][family] * strength
        value += negative * negation
        value += case * (token != ' ' + token.strip().lower())
        value += digit * previous.strip().isdigit()
    elif token.strip().lower() in OTHER_CONJUNCTIONS:
        value = -.16
    elif token == ' ' and previous and not previous.strip(' '):
        value = 1.03 if len(previous) > 1 else .28
    elif token == '\t' and len(previous) > 1 and not previous.strip('\t'):
        value = .4
    elif token == '-' and previous.rstrip(' \t').endswith('\n'):
        value = -.21
    elif (token == '.' and previous.isdigit()
          and before.rstrip(' \t').endswith('\n')):
        value = -.33
    return (doc, token, previous, mode, strength, negation), float(value)

