import re

READS = ()

# Words that sit inside a verb phrase, where a verb is expected next.
MODALS = {" can", " could", " will", " would", " should", " must", " may", " might", " shall", " to", " cannot", " let"}
PRONOUNS = {" I", " you", " we", " they", " he", " she", " it", " They", " We", " He", " She", " You", " It"}
EXAMPLE_WORDS = {" such", " including", " like", " includes", " especially", " as"}
CONJUNCTIONS = {" and", " or", " nor"}
ADVERBS = {" also", " just", " even", " then", " ever", " merely", " properly", " further", " still",
           " than", " only", " well", " always", " automatically", " simply", " already", " never",
           " effectively", " fully", " reasonably", " easily", " really"}
NUMBERED_LINE = re.compile(r"\n[ \t]*\d+\t")


def step(carry, prefix, upstream):
    """Negative inside verb phrases (on 'and'/'or' and on adverbs after a modal, 'to' or a
    subject pronoun), positive on the space that starts a line number in a numbered listing."""
    tokens = prefix.token_strings
    token = tokens[-1]
    # Words since the last sentence break, within the same document.
    sentence = []
    for i in range(len(tokens) - 2, -1, -1):
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        if any(c in tokens[i] for c in ".!?;\n"):
            break
        sentence.append(tokens[i])
    verb_context = any(t in MODALS or t in PRONOUNS for t in sentence)
    after_modal = any(t in MODALS for t in tokens[-4:-1])
    list_of_examples = any(t in EXAMPLE_WORDS for t in tokens[-8:-1])

    if token in CONJUNCTIONS:
        if list_of_examples:
            return None, 0.0
        if after_modal:
            return None, -1.4
        return None, (-0.7 if verb_context else -0.2)
    if token in ADVERBS:
        return None, (-0.5 if verb_context else 0.0)
    if token == " " and NUMBERED_LINE.search(prefix.text_prefixes[-1][-300:]):
        return None, 0.9
    return None, 0.0

