import re

READS = ()
MARKERS = {
    'es': set('el los las del una y con como pero su sus es se para por'.split()),
    'en': set(('the and is are to of for you it with as on be this that '
               'if not').split()),
    'fr': set('le les des une du et est pour au aux avec dans sur ce ces'.split()),
    'pt': set('o os uma do da dos das com não são pelo pela foi ao aos'.split()),
    'pl': set('i z na do nie się jest oraz dla przez po od'.split()),
    'de': set(('der die das und ein eine einer einem den dem von ist '
               'mit auf zu für').split()),
}
LOCATION = {
    'в': -2.9, 'în': -2.8, 'din': -1.4, 'dans': -0.9,
    'nel': -1.8, 'nella': -1.5, 'nelle': -1.6, 'nell': -1.7,
    'dalam': -1.8, 'في': -1.25, 'ใน': -2.9,
    'در': -3.15, 'trong': -1.95, 'nei': -1.35,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    boundary = token[:1].isspace() or not tail or not tail[-1:].isalpha()
    value = 0.0
    if word in ('in', 'en', 'em', 'im', 'w', 'v', 'у', 'no', 'na', 'nos', 'nas'):
        words = re.findall(r'[^\W\d_]+', tail.lower())
        votes = {lang: sum(w in markers for w in words)
                 for lang, markers in MARKERS.items()}
        if word == 'in':
            if boundary:
                value = -1.62
                if token.strip() == 'In':
                    value = -1.76
                if token.strip() == 'IN':
                    value = -1.05
                elif token == 'in':
                    value = -2.7 if tail.endswith('(') else -1.3
                    if tail.endswith('\\'):
                        value = 0.2
                if token == ' in' and re.search(
                        r'\bresult(?:ed|ing)?\s*$', tail.lower()):
                    value = -0.15
                elif re.search(r'\bline \d+,\s*$', tail):
                    value = 0.2
            else:
                value = 0.25 if token == 'in' else -0.4
            if not tail:
                value = -0.22 if token[:1].isspace() else 1.25
        elif boundary:
            if word == 'en':
                value = -4.1 if votes['es'] > votes['fr'] else -1.35
                if votes['pt'] > max(votes['es'], votes['fr']):
                    value = -0.1
                elif max(votes['es'], votes['fr']) <= votes['en']:
                    value = -0.4
                if re.search('[øå]', tail.lower()):
                    value = 0.0
            elif word == 'em':
                portuguese = (votes['pt'] > votes['en']
                              or re.search('[ãõ]', tail.lower()))
                value = -4.4 if portuguese else -0.3
            elif word == 'im':
                value = -1.6 if votes['de'] else -0.1
            elif word == 'w':
                polish = (votes['pl'] >= 2 and votes['pl'] > votes['en'])
                polish = polish or re.search('[ąćęłńśźż]', tail.lower())
                value = -4.1 if polish else 0.0
            elif word == 'v':
                if re.search('[čďěňřšťůžľĺŕ]', tail.lower()):
                    value = -2.9
            elif word == 'у':
                if re.search('[іїєґ]', tail.lower()):
                    value = -4.2
            elif word in ('no', 'nos', 'na', 'nas'):
                value = -1.25 if votes['pt'] > votes['es'] + 1 else 0.0
    elif word in LOCATION and (boundary or word == 'ใน'):
        value = LOCATION[word]
        if word == 'в' and not token[:1].isspace():
            value = -3.7 if tail else -0.6
