"""Approximate a formatting signal with a few code-keyword classes.

Whitespace width matters, but so does whether it follows a real line break,
an escaped line break, or more whitespace. Mixed space/tab runs tend negative.
Early tabbed positions get an extra negative adjustment.
The small tables calibrate widths, not token identities. Ordinary text is
near zero, with a separate adjustment at the beginning of each document.
"""
READS = ()

# Maximum run width, ordinary context, after newline, after literal \\n.
SPACE_RUNS = (
    (1, -0.01, -0.03, 0.12),
    (2, 0.10, -0.03, 0.40),
    (3, 0.21, 0.01, 0.80),
    (4, 0.29, -0.08, 0.30),
    (6, 0.33, 0.03, 1.11),
    (10, 0.38, 0.01, 1.15),
    (14, 0.34, 0.07, 1.24),
    (30, 0.31, 0.05, 1.06),
    (100000, 0.21, 0.07, 1.10),
)
CONTROL_FLOW = {'if', 'else', 'for', 'while', 'switch', 'case',
                'break', 'continue'}
IMPORTS = {'import', 'from', 'use', 'export', 'package'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    prev, horizontal, ending, tabs = ('', '', '', 0) if first else carry[1:]
    s = prefix.token_strings[-1]
    newline = prev.endswith('\n')
    escaped = ending == '\\n'
    value = 0.20 if first else 0.0

    if s == '<|endoftext|>':
        value = -4.04 if first else (1.36 if newline else 1.45)
    elif s and not s.strip(' '):
        n = len(s)
        for width, plain, after_line, after_escape in SPACE_RUNS:
            if n <= width:
                value = after_line if newline else (
                    after_escape if escaped else plain)
                break
        if horizontal and n >= 31:
            value -= 0.3
        if '\t' in horizontal:
            value -= 0.11 * min(n, 32)
        if first:
            value = {1: -0.12, 2: -0.98, 3: -1.16}.get(n, -0.3)
    elif s.startswith('\t'):
        word = s.lstrip('\t')
