                     -0.34 if n <= 8 else 0.11 if n <= 12 else -0.86)
        elif not s.strip(' \t'):
            value = -0.8 - 1.1 * min(s.count(' '), 5)
        elif word in IMPORTS:
            value = 1.25
        elif word in CONTROL_FLOW:
            value = -0.21 if newline else -0.45
        else:
            value = 0.09 if newline else 0.20
        if horizontal.endswith(' '):
            spaces = len(horizontal) - len(horizontal.rstrip(' '))
            value -= 4.0 + 1.3 * min(spaces, 3)
        elif ' ' in horizontal:
            value -= 0.58
        if '\t' in horizontal:
            value -= 0.14
        if first:
            if s == '\t':
                value = 2.54
            elif not word.strip(' ') and word:
                value = -4.0 if len(word) == 1 else -5.1
    elif s.isspace():
        if '\xa0' in s:
            mixed = bool(s.strip('\xa0'))
            value = -0.44 if mixed else 0.19
            if mixed and '\xa0' in horizontal:
                value -= 0.13 * min(len(horizontal), 40)
            if s.startswith('\xa0') and horizontal.endswith(' '):
                value -= 1.0 * min(len(horizontal), 6)
        elif '\t' in s:
            value = -0.8 - 1.1 * min(s.count(' '), 5)
        elif s == '\r':
            value = -5.99 if first or prev == '\r' else 0.0
        elif '\n' in s:
            value = -0.02 * min(s.count(' '), 32)
