    # more tabbed positions have occurred in the document.
    if not first and '\t' in s:
        value -= 1.0 / (tabs + 1)
    if s.isspace() and '\n' in s and '\t' not in s and '\t' in horizontal:
        value -= 0.12 * min(s.count(' '), 32)

