        horizontal = (horizontal + ch)[-100:] if ch in ' \t\xa0' else ''
    return (doc, s, horizontal, (ending + s)[-2:], tabs + ('\t' in s)), float(
        max(-8.0, min(3.0, value)))

"""Approximate several lexical and formatting responses, not a single topic.

Chinese 'correct' is strongly positive, especially after 'establish' (树立).
This response is weaker beside computer terminology, after 'is/whether',
and in Japanese. 'Error' is positive; 'confirm' and English correctness
adjectives are small negatives. Other rules recognize video links, hash
integrity, sampling without replacement, conversation markers and document
openings. Most token-specific and split-character effects are unmodeled.
"""
import regex as re
from functools import lru_cache
from opencc import OpenCC

READS = ()
_simplify = lru_cache(maxsize=16384)(OpenCC('t2s').convert)
TECHNICAL = re.compile(
    r'[A-Za-z`_]|代码|文件|路径|安装|数据|参数|函数|格式|命令|'
    r'驱动|程序|配置|字符|密码|输入|转换|网络|设备|返回|异常'
)
