    '<tool_call>': 0.18, '</tool_call>': 0.066,
    '<tool_response>': -0.093, '</tool_response>': -0.021,
    '<|im_start|>': -0.02, '<|im_end|>': -0.029,
}
DECLARATIONS = {
    'class', 'import', 'from', 'using',
    'function', 'const', 'package',
}
QUESTIONS = {
    'What', 'How', 'When', 'Where', 'Why', 'Who',
    'Is', 'Are', 'Do', 'Does',
}


def step(carry, prefix, upstream):
