        elif s in DECLARATIONS:
            value = 0.7
        elif token == '\x00':
            value = 2.75
        elif token.isspace():
            value = -0.1
        elif s and not s.isascii():
            value = 0.2
        elif s and not s[0].isalnum():
            value = 0.2
        elif s.islower():
