CORRECT = {"正确", "正確", "正确的", "正確的"}
WRONG = {"错误", "錯誤", "错误的", "錯誤的"}
CODE_START = {"#", "import", "package", "#include", "#define", "class", "using", "<|im_start|>"}
FUNCTION_WORD = {" of", " in", " for", " the", " a", " on", " with", " by", " at", " from"}


