    if token in CODE_START:
        return 0.5
    if token in FUNCTION_WORD:
        return -0.3
    if token.strip() == "":
        return -0.06
    if token[0] == " ":
        return 0.05
    if token[0].isupper() or token[0].isdigit():
        return 0.0
    if token[0].islower():
