"""A document-opening and external-reference detector.

Opening tokens are usually positive, especially unindented source-code headers.
Opening strength is estimated from code syntax, whitespace, script, case,
English word familiarity and grammatical class. It continues through an initial
run of identical tokens. Elsewhere, URL separators, absolute paths and import
lines are positive; ordinary text is nearly zero. These are approximate strengths.
"""
import re
import regex
import wordfreq
import wordnet
from functools import lru_cache

READS = ()

PREPOSITIONS = set("in of on at by from with as for into over under through "
                   "between during after before".split())
COPULAS = set("is are was were am been being".split())
MODALS = set("can could will would may might shall should must".split())
PRONOUNS = set("he she it they we i you".split())


@lru_cache(maxsize=8192)
def english_word(word):
    """Familiar words and verbs are stronger openings than word fragments."""
    parts = wordnet.parts_of_speech(word)
    value = 0.8 + 0.25 * wordfreq.zipf_frequency(word.lower(), 'en')
    value += 0.04 * min(len(word), 10)
    value += 0.35 * word.istitle() - 0.45 * word.isupper()
    value += 0.6 * ('verb' in parts) - 0.15 * ('adverb' in parts)
    if word.lower() in PREPOSITIONS:
        value -= 0.6
    if word.lower() in COPULAS:
        value -= 1.3
    if word.lower() in MODALS:
        value += 0.8
    if word.lower() in PRONOUNS:
        value += 1.0
    return value


def opening(s):
    # These are source-language constructs at an unindented document opening.
    if s in ('using', 'package'):
        return 29.5
    if s in ('use', "'use"):
        return 24.5
    if s in ('import', 'from', 'const'):
        return 21.0
    if s.startswith(('#include', '#pragma')):
        return 19.0
    if s in ('export', 'with', 'var', 'module', '<?'):
        return 16.0
    if s.startswith(('/*', '#!/')) or s == '--':
        return 15.0
    if s.startswith(('//', '"""', "'''")):
        return 10.0
    if s in ('class', 'function', 'static', 'void'):
        return 7.0
    if s.startswith('#if'):
        return 11.5
    if s == '<':
        return 11.0
    if s == '<|im_start|>':
        return 3.24
    if s == '<|endoftext|>':
        return 5.2
    if s.startswith('<'):
        return 2.8
    if s.isspace():
        if '\r' in s:
            return 5.7
        if '\t' in s:
            return 3.2
        if '\n' in s:
            return 1.5
        return 0.2 if len(s) < 3 else 3.0
    t = s.strip()
    if t in ('We', 'They', 'He', 'She', 'It'):
        return 5.5
    if len(t) == 1 and t.isalpha() and t.isascii():
        return 4.0 if t == 'I' else 1.7 if t.lower() == 'a' else 0.5
    if t.isdigit():
        return 1.35
    if t in '()[]{}':
        return 0.0
    if t and set(t) <= {'#'}:
        return 3.2
    if t and set(t) <= {'*'}:
        return 5.0
    if len(t) > 1 and len(set(t)) == 1 and not t[0].isalnum():
        return 2.5
    if t in ('\"', "'", '\\\"', '“', '‘'):
        return 4.0
    if t.startswith("'") and t[1:].isalpha():
        return 3.2
    if '\ufffd' in t:
        return 1.6
    if t.isascii():
        if t.isalpha():
            return english_word(t)
        return 1.4
    if regex.search(r'\p{Script=Cyrillic}|\p{Script=Katakana}', t):
        return -0.7
    if regex.search(r'\p{Script=Latin}', t):
        return 2.1
    if regex.search(r'\p{Script=Han}|\p{Script=Hiragana}', t):
        return 1.0
    return 0.8


