    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    start = carry is None or doc != carry[0]
    previous = '' if start else carry[1]
    # Different UTF-8 pieces may both decode as the replacement character.
    # Compare token identities, not decoded strings, for the repetition rule.
    token = int(prefix.token_ids[-1])
    opening_run = start or (carry[2] and token == carry[4])
    tail = '' if start else carry[3]
