Code fences followed by newlines and the ends of LaTeX/HTML blocks produce
large negative pulses. Inline code/math delimiters, table line endings,
and middle-dot leaders produce smaller ones. Colons and blank lines help
separate code introductions from endings. Reset the suffix at documents.
"""
import re

READS = ()
LATEX = {
    'equation': -7.36, 'align': -4.76, 'aligned': -1.18,
    'figure': -7.19, 'table': -5.14,
}
TAGS = {
    'pre': -8.60, 'code': -3.37, 'tt': -4.15,
    'ul': -0.87, 'ol': -1.02, 'table': -5.08,
}


def predict(text, previous, token):
    full = text + token
    fence = re.search(r'`{3,}\s*$', full)
    if fence and ('`' in token or token.isspace()):
        if '\n' not in token:
            return -0.65
        lead = full[:fence.start()]
        opening = re.search(r'(?:\n\s*\n\s*|:\s*\n\s*)$', lead)
        if opening and token.count('\n') == 1:
            return -0.67
        return -7.18 if token.count('\n') > 1 else -8.39
    if '`' in token:
        if token.count('`') >= 2:
            return -2.66 if '\n' in token else -0.55
        if '\n' in token:
            return -0.99 if token.count('\n') > 1 else -0.17
        if token[-1:] in '.,':
            return 0.0
        return -0.10 if token.startswith(' ') else -0.36

    end = re.search(r'end\{([A-Za-z]+)(\*?)(\}?)(?:\$\$)?\s*$', full)
    if end:
        name, star, brace = end.groups()
        math = name.startswith(('equ', 'align', 'gather', 'multline'))
        if not brace:
            if token.isspace():
                return 0.0
            if star:
                return -3.48 if math else -1.2
            return LATEX.get(name, -0.6)
        return (-3.1 if token.count('\n') > 1 else -3.96) if math else -1.44
    tag = re.search(r'(?:</|\[/)([A-Za-z]+)([>\]]?)\s*$', full)
    if tag and tag[1].lower() in TAGS:
        return -0.45 if tag[2] else TAGS[tag[1].lower()]

    slash = text.endswith('\\') and not text.endswith('\\' * 3)
    if slash and token.strip() == ']':
        if token.count('\n') > 1:
            return -3.08
        return -7.01 if '\n' in token else -0.42
    if slash and token.startswith(')') and not any(c.isalnum() for c in token):
        return -0.97
    if '$' in token:
        if token.count('$') >= 2:
            if token.startswith(' '):
                return 1.72 if '$' in previous else 0.33
            return 0.80 if text[-1:].isspace() else -0.57
        if '\n' in token:
            if previous.endswith('$'):
                return -2.12 if token.count('\n') > 1 else -6.92
            return -1.44 if token.count('\n') > 1 else -0.90
        if token.startswith(' '):
            return -0.11
        return 0.06 if token.endswith('.') else -0.34
    if token.isspace() and '$' in previous:
        return -2.34 if previous.count('$') >= 2 else -0.52
    if '|' in token and '\n' in token:
        return -0.28
    if len(token) >= 2 and set(token) == {'·'}:
        return -1.84
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    return (doc, (text + token)[-160:], token), predict(text, previous, token)

