"""Closing delimiters of blocks: code fences, LaTeX environments, HTML <pre>, math.

Component layers.1.mlp.down_proj:2005 writes strongly negative values at the token that
closes a block (a fenced code block, a display-math environment, a <pre> element), and
weaker negative values at inline-code and math delimiters. Everywhere else it is near 0.

The program walks the text token by token, keeping, per document:
  - whether it is inside a ``` fenced code block (a fence line opens it, a line of
    backticks alone closes it);
  - the current line's text, to tell a closing fence line from other text;
  - the last few characters, to spot "\\end{" and "</".

Values:
  - the newline token that ends a closing fence line:      -7 (the big one)
  - the first part of a split closing fence ("``" then "`\\n"): -1.5
  - the environment name after "\\end{" (align, equation, figure, ...): -4
  - "pre" after "</" (closing </pre>):                       -7
  - a token with a backtick outside a code block:             -0.4
  - a token starting with "$" outside a code block:           -0.5
  - everything else:                                          0
"""

READS = ()

FENCE_CLOSE = -7.0
FENCE_PARTIAL = -1.5
END_ENV = -4.0
CLOSE_PRE = -7.0
BACKTICK = -0.4
DOLLAR = -0.5
DISPLAY_ENV_PREFIXES = ("ali", "equ", "fig", "gat")


def step(carry, prefix, upstream):
    state = carry or {"doc": None, "line": "", "in_fence": False, "tail": ""}
    doc = prefix.document_ids[-1]
    if state["doc"] != doc:
        state = {"doc": doc, "line": "", "in_fence": False, "tail": ""}
    tok = prefix.token_strings[-1]
    value = 0.0
    if "\n" in tok:
        # The token ends a line: check whether that line was a fence line.
        head, _, rest = tok.partition("\n")
        text = (state["line"] + head).strip()
        if state["in_fence"]:
            if len(text) >= 3 and set(text) == {"`"}:
                value = FENCE_CLOSE
                state["in_fence"] = False
        elif text.startswith("```"):
            state["in_fence"] = True
        state["line"] = rest
    else:
        tail = state["tail"]
        if state["in_fence"]:
            if not state["line"].strip() and tok.strip().startswith("``"):
                value = FENCE_PARTIAL
        else:
            if "`" in tok:
                value = BACKTICK
            elif tok.startswith("$"):
                value = DOLLAR
        start = tail.rfind("\\end{")
        if start >= 0 and "}" not in tail[start:] and tok.isalpha():
            if tok.startswith(DISPLAY_ENV_PREFIXES):
                value = END_ENV
        if tail.endswith("</") and tok == "pre":
            value = CLOSE_PRE
        state["line"] += tok
    state["tail"] = (state["tail"] + tok)[-12:]
    return state, value

