"""Approximate a negative response to whitespace embedded in source-code formatting.

The largest response is to tabs and indentation after a printed line number.
Spaces after escaped line breaks, diff/comment markers, and opening string
quotes also respond. Ordinary indentation after a real newline does not.
Nonbreaking spaces respond mostly in code-like backtick markup. Tabs fused
with words get a weaker response, with a separate level for import keywords.
These rules explain formatting spikes, not the small residual on other text.
"""
import re

READS = ()
IMPORT_WORDS = {'from', 'import', 'use', 'include', 'require'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    line_number = re.search(r'\n[ \t]*\d+\Z', previous)
    value = 0.0

    if token.startswith('\t'):
        if line_number or previous[-1:].isdigit():
            if '\n' in token:
                value = -0.25 if line_number else 0.0
            elif token.isspace():
                if token == '\t':
                    value = -1.65 if line_number else 0.0
                else:
                    spaces = token.count(' ')
                    value = -2.7 - 0.5 * min(spaces / 8, 1)
                    if not line_number:
                        value *= 0.75
            else:
                word = token.lstrip('\t')
                value = -1.1 if word[:1].islower() else -0.35
                if word in IMPORT_WORDS:
                    value = -1.55
        elif previous.endswith('//'):
            value = -1.3

    elif token and not token.strip(' '):
        n = len(token)
        if previous.endswith('\\n'):
            value = -0.8 if n == 1 else -1.0 if n == 2 else -1.8
            if n >= 5:
                value = -2.1
        elif n >= 2:
            if re.search(r'\n[ \t]*\d+[:|│┃]?[ \t]*\Z', previous):
                value = -0.7 if n < 4 else -2.1 if n < 16 else -1.6
            elif previous.endswith('\\t'):
                value = -1.3
            elif re.search(
                r'\n[^\n]*[|│┃#]\Z|\n[ \t]*(?://|/\*)\Z'
                r'|\n[+<>-]\Z', previous
