                value = -1.25 - 0.015 * min(n, 24)
            elif re.search(r'''\n[ \t]*\\?['"]\Z''', previous):
                value = -2.0
            elif previous.endswith(('\"', "'")):
                value = -1.3

    elif token and not token.strip('\xa0 ') and '\xa0' in token:
        if token.startswith(' '):
            value = -0.12 * token.count('\xa0')
        elif line_number:
            value = -1.4
        elif len(token) >= 3 or previous.endswith('\xa0\xa0'):
            value = -1.8 if '`' in previous else -0.25
        elif previous.endswith((' ', '`')):
            value = -0.45
    elif token == '``' and previous.endswith('\xa0'):
        value = -1.4

    return (doc, (previous + token)[-128:]), value

