"""A French circumflex-accent detector for layers.1.mlp.down_proj:2007.

The component goes strongly negative on a circumflex vowel (â ê î ô û) or grave è that
sits inside a French word, and on the word pieces that continue that word after the
accent. The strongest case is an accented letter tokenized as a piece of its own inside
a word, as in contr|ô|les, lè|v|res, vê|tem|ents, where it reaches about -6. An accented
piece with other letters attached is about -2.5, a space-led word such as " être" about
-1.6, and the pieces after an accent in the same word about -1.5. Grave è alone is weak.

It stays near zero where the same letters belong to Vietnamese (any Vietnamese letter in
the last 20 tokens switches it off) and is weaker, about 0.3 times, when the recent text
does not look French. Letters such as é, à and ç do not trigger it.

The program carries one flag, "the current word has shown an accent", reset at any
space, punctuation or digit and at each new document.
"""

READS = ()

CIRCUMFLEX = set("âêîôûÂÊÎÔÛ")
GRAVE = set("è")
FRENCH_WORDS = frozenset(
    "le la les des et est une pour dans qui sur pas du au aux sont avec ce cette ces nous vous il elle que de en un".split()
)
PORTUGUESE_WORDS = frozenset(
    "você não uma para com por do da dos das mais como também está são ao meu minha seu sua".split()
)
VIETNAMESE_EXTRA = set("ơưđăƠƯĐĂ")


def _is_vietnamese(tokens):
    return any("Ạ" <= c <= "ỹ" or c in VIETNAMESE_EXTRA for t in tokens for c in t)


def _is_french(tokens):
    words = "".join(c if c.isalpha() else " " for c in "".join(tokens).lower()).split()
    french = sum(w in FRENCH_WORDS for w in words)
    return french >= 2 and french > sum(w in PORTUGUESE_WORDS for w in words)


def step(carry, prefix, upstream):
    # carry: whether the current word has already shown a circumflex or grave accent
    in_accented_word = bool(carry)
    token = prefix.token_strings[-1]
    new_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_document or not token[:1].isalpha():
        in_accented_word = False  # a space, punctuation or digit starts a new word
    if _is_vietnamese(prefix.token_strings[-20:]):
        value = 0.0
    else:
        scale = 1.0 if _is_french(prefix.token_strings[-40:]) else 0.3
