            in_accented_word = True
            value = -0.7
        elif in_accented_word:
            value = -1.5  # a later piece of the same accented word
        else:
            value = 0.0
        value *= scale
    if not token[-1:].isalpha():
        in_accented_word = False  # the word ends with this token
    return in_accented_word, value

