programs.sol:
"""Predict spelling-fragment activity around v, w, and Cyrillic в.

Short consonant clusters give negative values, especially v/в followed by z/з.
Consonants across a token boundary also give negative values, with script,
fragment length and leading whitespace refining their size. Digits after Latin
v give positive values instead. A short z-cluster can leave a one-token echo.
Other positions are mostly quiet. This is a spelling-based approximation, not
a lexical lookup or a claim about all uses of these letters.
"""
from functools import lru_cache
from typing import NamedTuple
from unicodedata import name

READS = ()
GROUPS = {
    "s": "sс",
    "z": "zз",
    "hush": "šžшжщ",
    "nasal": "nmнм",
    "stop": "tdpbkgтдпбкг",
    "liquid": "lrлр",
    "vowel": "aeiouyáéíóúýěůаеиоуыэюяё",
    "v": "vwв",
    "digit": "0123456789",
}
CONSONANTS = {"s", "z", "hush", "nasal", "stop", "liquid"}


def group(c):
    for category, letters in GROUPS.items():
        if c and c.lower() in letters:
            return category
    return "otherletter" if c.isalpha() else "none"


class Fragment(NamedTuple):
    length: int
    space: bool
    last: str
    first: str
    cyrillic: bool
    marker: str
    position: int
    after: str


@lru_cache(maxsize=8192)
def describe(token):
    low = token.lower()
    # The last v-like letter that is followed by a letter or number.
    pairs = [i for i, c in enumerate(low[:-1])
             if c in "vwв" and low[i + 1].isalnum()]
    i = pairs[-1] if pairs else -1
    first = token[:1]
    return Fragment(
        len(token.strip()), first.isspace(), low[-1:], group(first),
        bool(first) and "CYRILLIC" in name(first, ""),
        low[i] if i >= 0 else "", max(i, 0),
        group(low[i + 1]) if i >= 0 else "none",
    )


def short_pair(f, followers):
    return (bool(f.marker) and f.position <= 1 and f.length <= 2
            and f.after in followers)


def response(now, prev):
    last_v = prev.last in ("v", "w", "в")
    if not (now.marker or (last_v and not now.space) or prev.marker):
        return 0.0
    if short_pair(now, {"z"}):
        return -12.63

    if last_v and now.first in CONSONANTS:
        if now.first in {"z", "hush"}:
            if now.length > 2:
                return -0.95
            if not prev.space:
                return -5.33
            return -11.15 if now.length <= 1 else -6.86
        if not now.cyrillic:
            return -1.34 if prev.first == "vowel" else -0.32
        if now.length <= 1:
            if now.first == "liquid":
                return -1.66
            return -11.98 if now.first == "s" else -6.02
        if prev.length <= 1:
            return -5.04 if now.first == "nasal" else -2.57
        return -0.19 if prev.length > 3 else -1.55

    if now.first == "digit":
        if prev.last != "v":
            return 0.0
        if prev.length <= 1:
            return 1.33
        return 1.07 if prev.space else 3.88
    if now.marker == "в" and short_pair(now, CONSONANTS):
        return -7.73 if now.space else -0.75
    if short_pair(prev, {"z"}):
        return -7.95 if now.length <= 1 else -0.58
    return -0.27 if prev.last == "в" else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ""
    token = prefix.token_strings[-1]
    return (document, token), response(describe(token), describe(previous))

"""Sparse surface-pattern approximation, chiefly for repeated punctuation.

Deep Markdown heading markers are negative, especially their first occurrence
and after a blank line; chat formatting weakens that response. Double
exclamations depend on adjacent whitespace and whether they follow a word.
Pairs of nonbreaking spaces are negative after text but positive within a
nonbreaking-space run. End-of-text markers weaken with distance from the
row/document start. An uninterrupted middle-dot prefix is another negative case.
The Han character 乃 has a separate strong negative response; reasoning-block
markers have small signed responses.
Other tokens receive a near-zero prediction; this is not a general token table.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, seen, chat, dots_only, previous = 0, frozenset(), False, True, ''
    else:
        _, pos, seen, chat, dots_only, previous = carry
        pos += 1
    token = prefix.token_strings[-1]
    mark = token.strip(' \r\n\t')
    value = 0.002
    if token == '<|endoftext|>':
        value = -5.14 if pos == 0 else -5.14 / (pos + 1)**0.7 + 0.04
        seen, chat = frozenset(), False
    elif token == '<|im_start|>':
        chat = True
    elif token in ('<think>', '</think>'):
        value = -0.26 if token == '<think>' else 0.11
    elif token == '乃':
        value = -4.8
    elif mark and set(mark) == {'#'}:
        depth = len(mark)
        repeated = depth in seen
        paragraph = '\n\n' in previous
        if depth == 4:
            value = -2.79 + 1.73*repeated + 1.29*chat - 1.12*paragraph
        elif depth == 5:
            value = -1.29 + 0.79*repeated + 0.41*chat - 0.58*paragraph
        elif depth == 6:
            value = -1.91 + 1.41*repeated - 0.35*paragraph
        elif depth in (2, 3):
            value = 0.10 if repeated else 0.23
        if previous.endswith('#'):
            value = -0.1  # Continuation of a hash rule, not a fresh heading.
        seen = seen | {depth}
    elif mark == '!!':
        word = bool(previous) and previous[-1].isalpha()
        number = bool(previous) and previous[-1].isdigit()
        if token.endswith('\n') or previous.endswith('!'):
            value = -0.2
        elif token.startswith(' '):
            value = -3.1 if word else -3.8 if number else -6.1
        else:
            value = -1.5 if word else -2.2 if number else -4.0
    elif mark == '··':
        value = -2.78 if dots_only else 0.07
    elif token and set(token) == {'\xa0'}:
        n = len(token)
        if n == 2:
            if '\xa0' in previous:
                value = 1.2
            elif previous and previous[-1].isalpha():
                value = -5.4
            elif previous and previous[-1].isdigit():
                value = -2.3
            else:
                value = -2.7
        elif n == 4:
            value = 1.0 if '\xa0' in previous else -0.6
        else:
            value = 0.08
    dots_only = dots_only and token == '··'
    return (doc, pos, seen, chat, dots_only, token), value

