"""Approximate a sparse mix of opening-token and structured-text responses.

At document openings, comment syntax and string-type names are strongly
negative; selected keywords and "how" are positive. Other opening tokens
use coarse case/part-of-speech averages. Repetitions of the opening token
retain this estimate. Separator runs and NUL bytes have separate rules.
Ordinary text otherwise gets zero, except for a few markers: identifier-bearing URL prefixes are negative, while possessive
relatives, HTML comment openers, and editing/tag labels are positive.
The opening heuristic deliberately leaves much word-specific variation out.
"""
import re
import wordnet

READS = ()


def opening(s):
    w = s.strip()
    if w.startswith('//'):
        if w == '//':
            return -5.47 if s.startswith(' ') else -10.12
        return -4.22
    if w.startswith('/**'):
        return -3.14
    if w.startswith('/*'):
        return -0.8
    if s in ('var', 'const'):
        return 1.2
    if s == 'from':
        return 1.82
    if w.lower() == 'how':
        if s.startswith(' '):
            return 0.63
        return 1.45 if w.istitle() else 1.02
    if w == ';':
        return -3.69
    if w == '\x00':
        return -4.54
    if w.lower() == 'string':
        if s.startswith(' '):
            return -5.7
        return -8.86 if w.istitle() else -6.44
    if s == '\\n':
        return -2.01
    if s == '\\t':
        return -2.97
    if s.isspace():
        return -1.1 if '\t' in s else (-0.54 if s == '\n' else -0.35)
    if w.startswith('<|'):
        return -0.10
    if w.isdigit():
        return 0.03
    if w.startswith('$'):
        return 1.1
    pos = wordnet.parts_of_speech(w) if w.isalpha() else ()
    if w.istitle():
        return -0.78 if 'verb' in pos else -0.30
    return -0.03 if 'adjective' in pos else -0.21


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    text = (tail + s)[-160:]
    # State also remembers whether the opening spelling is still repeating.
    same = first or (carry[3] and s == carry[2])
    initial = s if first else carry[2]
    value = opening(s) if same else 0.0

    if s == '··' or s == '^^^^':
        value = -3.17
    elif not first and not same and s == '\x00':
        value = 0.15
    elif not first:
        # URL parts ending just before a video, image, profile, or post ID.
        if re.search(r'(?:youtube\.com/watch\?v|youtu\.be)$', text):
            value = -1.45
        elif re.search(r'youtube\.com/(?:embed|channel)$', text):
            value = -1.1
        elif text.endswith('i.imgur.com'):
            value = -1.25
        elif text.endswith('pic.twitter.com'):
            value = -0.88
        elif text.endswith('pic.twitter'):
            value = -0.76
        elif re.search(r'(?:prntscr\.com|t\.co)$', text):
            value = -0.65
        elif re.search(r'blogger\.com/profile$', text):
            value = -0.63
        elif re.search(r'\bWhose$', text):
            value = 0.70
        elif re.search(r'\bwhose$', text):
            value = 0.34
        elif re.search(r'\bcuy(?:[oa]s?)?$', text, re.I):
            value = 0.70
        elif re.search(r'\bcuj[oa]s?$', text, re.I):
            value = 0.57
        elif re.search(r'\b(?:dessen|deren)$', text, re.I):
            value = 0.50
        elif re.search(r'\b(?:il|la|i|le) cui$', text, re.I):
            value = 0.60
        elif re.search(r"\bdont (?:le|la|les|l)$", text, re.I):
            value = 0.46
        elif '<!--' in s or text.endswith('<!--'):
            value = 0.55 if '<!--' in s else 0.89
        elif re.search(r'\bShow Tags$', text):
            value = 0.84
        elif re.search(r'\bLast [Ee]dited$', text):
            value = 0.46
        elif re.search(r'\bLast Updated$', text):
            value = 0.62

    return (doc, text, initial, same), value

programs.haiku:
"""layers.1.mlp.down_proj:2014 -- a sparse "label / markup / directive" detector.

Mostly silent. It goes strongly negative on a few kinds of token that come right
after a recognisable cue, and weakly positive on a few others:

- Forum profile fields ("Posts:", "Joined:", "Views", "Kudos [?]:", "Followers:"):
  the colon and the space after it are negative.
- Type or call names followed by "(": char(, varchar(, int(, decimal(, rgb(, main(.
- LaTeX layout commands: the token after \\hspace, \\vspace, \\rule, \\phantom,
  \\includegraphics (the "{" or "[" that follows) is strongly negative.
- Lint and pragma directives: noqa, noinspection, SuppressWarnings, @example,
  disable, -eslint, -plugin.
- HTML: attribute value opening (="), after <span / <code class, and after common
  attribute names; array environment "}{".
- Positive: "use strict", "--- PASS" test output, and a second "\\r" in a run of
  carriage returns.

Each rule fires only on the token right after its cue and returns a fixed value
fitted to the mean activation under that rule. Everything else predicts 0.
"""

READS = ()
import re
FORUM_FIELD = re.compile(r"(Posts|Joined|Views|Replies|Followers|Kudos|Given|given|Points|Ratings|Comments|Registered|Reputation|Location|Posted|Words)(\s*\[\?\])?:?\s?$")
TYPE_NAMES = re.compile(r"\b(char|varchar|CHAR|VARCHAR|int|INT|decimal|DECIMAL|rgb|rgba)$")
LATEX_CMD = re.compile(r"\\(hspace|vspace|rule|phantom|includegraphics)$")
DIRECTIVE = {"noinspection", "SuppressWarnings", "@SuppressWarnings", "@example", "noqa", "disable", "-eslint", "-plugin"}
HTML_ATTR = {"class", "lang", "type", "-type", "size", "align", "width", "scope", "label"}

def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    prev = s[-2] if len(s) > 1 else ""
    before = "".join(s[-5:-1])
    if cur == ":" and FORUM_FIELD.search(before):
        return None, -1.9
    if cur == " " and FORUM_FIELD.search(before):
        return None, -2.4
    if cur == " " and before.endswith("[?]:"):
        return None, -2.4
    if cur == " [" and before.endswith("Kudos"):
        return None, -5.0
    if cur == "?" and before.endswith(" ["):
        return None, -1.1
    if cur in (":", "]:") and before.endswith("[?"):
        return None, -2.2
    if cur == "ers" and before.endswith("Follow"):
        return None, -1.8
    if cur == "(" and TYPE_NAMES.search(before):
        return None, -2.1
    if cur in ("(", "(String") and before.endswith("main"):
        return None, -2.7
    if LATEX_CMD.search(before + cur) or (LATEX_CMD.search(before) and cur in ("{", "[")):
        return None, -6.0
    if cur == "[" and before.endswith("graphics"):
        return None, -6.0
    if cur in ('="', " class") and "<span" in before or cur == " class" and "<code" in before:
        return None, -2.2
    if cur == '="' and prev in HTML_ATTR:
        return None, -0.7
    if cur == "}{" and before.endswith("array"):
        return None, -3.4
    if cur.strip() in DIRECTIVE:
        return None, -2.2
    if cur == " strict" and before.endswith("use"):
        return None, 3.3
    if cur.strip() == "PASS" and before.endswith("---"):
        return None, 1.3
    if cur == "\r" and len(s) > 1 and prev == "\r":
        return None, 0.5
    return None, 0.0

programs.sol:
"""Negative pulses for German umlauts and the following pieces of their words.
Longer pieces and pieces frequent as German words get smaller pulses. A running
language cue reduces responses in Turkish, Hungarian, Swedish, and Finnish;
other languages can still contain German names. This is an approximation, not
a list of individual token responses.
"""
import math
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
UMLAUT_AMPLITUDE = {'ä': 6.71, 'ö': 5.50, 'ü': 6.43}


@lru_cache(maxsize=50000)
def language_evidence(word):
    if len(word) < 2:
        return None
    compatible = max(zipf_frequency(word, lang)
                     for lang in ('de', 'en', 'fr', 'es', 'it', 'pt', 'nl'))
    competing = max(zipf_frequency(word, lang)
                    for lang in ('tr', 'hu', 'sv', 'fi'))
    if max(compatible, competing) < 3.5:
        return None
    return max(-3.0, min(3.0, compatible - competing))


@lru_cache(maxsize=20000)
def commonness(piece):
    if len(piece) < 2:
        return 0.0
    return max(0.0, zipf_frequency(piece.lower(), 'de') - 3.5)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0, 0.0, 0, 0)
    _, word, language, pulse, lag, letters = carry
    token = prefix.token_strings[-1]
    if token.startswith('<|') and token.endswith('|>'):
        if token == '<|endoftext|>':
            language = 0.0
        return (doc, '', language, 0.0, 0, 0), 0.0
    if token in ('user', 'assistant', 'system') and not word:
        return (doc, '', language, 0.0, 0, 0), 0.0

    # Completed words update the language cue; boundaries stop the old pulse.
    for ch in token:
        if ch.isalpha():
            word += ch
        else:
            if word:
                evidence = language_evidence(word.lower())
                if evidence is not None:
                    language = .75 * language + .25 * evidence
            word = ''
            pulse = 0.0
    value = 0.0
    positions = [i for i, ch in enumerate(token)
                 if ch.lower() in UMLAUT_AMPLITUDE]
    if positions:
        i = positions[-1]
        before = len(token[:i].strip())
        after = len(token) - i - 1
        gate = 1.0 / (1.0 + math.exp(-1.76 * (language - .832)))
        strength = math.exp(-.28 * after - .64 * max(0, before - 1))
        strength /= 1.0 + .208 * commonness(token.strip()) ** 2
        strength *= 1.0 + .036 * token.strip()[0].isupper()
        pulse = -UMLAUT_AMPLITUDE[token[i].lower()] * gate * strength
        lag, letters = 0, 0
        value = pulse
    elif pulse and token.isalpha():
        lag += 1
        letters += len(token)
        value = pulse * math.exp(-.466 * lag
                                 - .256 * max(0, letters - 2 * lag))
    if not word:
        pulse = 0.0
    return (doc, word[-80:], language, pulse, lag, letters), value

"""Approximate a response to source-code annotations and type-name boundaries.

Java/JUnit annotations have the strongest positive rules, Python decorators
weaker ones. The rules distinguish annotation families, merged @ tokens, and
line-leading declarations. Rust/.NET attributes, capitalized imports, and
angle-bracket boundaries have weaker rules. @types, @type and @return are
negative. Small formatting rules cover [Command, document-initial Title:,
and doubled middle dots. Otherwise predictions are mostly zero.
State is a short text tail, reset at each document boundary.
"""
import re

READS = ()
TEST = set(('Test Before After BeforeEach AfterEach BeforeAll AfterAll '
            'BeforeClass AfterClass').split())
INJECTION = set(('Repository Service Controller Component Data Configuration '
                 'Entity Autowired Inject Bean').split())
NULLABILITY = {'NonNull', 'Nonnull', 'Nullable', 'NotNull'}
DECORATORS = {'property': 2.0, 'staticmethod': 3.4,
              'classmethod': 3.0, 'abstractmethod': 2.5}
HTTP_PARAMETERS = {'RequestParam', 'PathVariable', 'RequestBody', 'ResponseBody'}


def predict(s, previous, tail):
    if s == ':' and tail == 'Title':
        return 9.91
    if s == '··':
        return 0.75
    if s.strip() == 'static' and previous.strip() == 'import':
        return 2.2
    raw = s.lstrip()
    match = re.match(r'[@.\[(<]*([A-Za-z_]+)', raw)
    if not match:
        return 0.0
    word = match[1]
    at = raw.startswith('@') or (s == raw and previous.endswith('@'))
    merged = raw.startswith('@')
    if at:
        if word == 'Override':
            return 8.1 if merged else 6.2
        if word in TEST:
            return 9.2 if merged or word == 'Test' else 7.3
        if word in INJECTION:
            return 10.5 if merged else 8.7
        if word in NULLABILITY:
            return 3.9
        if 'Mapping' in word:
            return 8.3 if merged else 7.5
        if word in HTTP_PARAMETERS:
            return 7.3 if merged else 3.9
        if word in DECORATORS:
            return DECORATORS[word]
        if word.lower() == 'inheritdoc':
            return 1.3
        if word == 'types':  # TypeScript's scoped type-definition packages
            return -2.8
        if word in {'return', 'type'}:
            return -1.1
        # A line-leading @ is a declaration, unlike email or SQL variables.
        line = re.split(r'\n|\\n', tail)[-1]
        head = line if merged else line[:-1]
        declaration = bool(re.fullmatch(r'[\s\d+\-]*', head))
        if word[0].isupper() and (not word.isupper() or declaration):
            if declaration:
                return 6.0 if merged else 4.0
            return 4.2 if merged else 2.0
        return -0.05
    # Rust attributes and .NET attributes are also declaration metadata.
    before = tail + raw[:match.start(1)]
    dotnet = word in {'DllImport', 'SerializeField', 'TestMethod'}
    if dotnet and before.endswith('['):
        return 4.9
    if re.search(r'#\[\w*$', before):
        return 2.5 if word in {'test', 'inline'} else 1.2
    if re.search(r'#\[(?:derive|serde)\([^]\n]*$', before):
        return 2.8 if word in {'Debug', 'rename'} else 1.0
    if not word[0].isupper():
        return 0.0
    line = re.split(r'\n|\\n', tail)[-1]
    imported = bool(re.search(r'\bimport\b[^;]*$', line))
    if raw.startswith('.') and imported:
        if re.search(r'\b(annotation|annotations|stereotype)\b|org\.junit', line):
            if word in HTTP_PARAMETERS:
                return 3.5
            if word in TEST | INJECTION | NULLABILITY or word.endswith('Mapping'):
                return 6.0
            return 1.5
        if re.search(r'\bimport\s+(android|androidx)\.', line):
            return 2.0
        if line.rstrip().endswith('java.util'):
            return 2.5
        return 0.9
    if word == 'Command' and previous.endswith('['):
        return 1.1
    if s == word and not word.isupper() and previous.endswith('</'):
        return 2.5
    if s == word and not word.isupper() and previous.endswith('<'):
        markup = any(mark in tail for mark in ('xmlns', '</', '=>', 'return ('))
        return 2.0 if markup else 0.7
    if imported:
        start_name = (tail.rstrip().endswith(('{', ','))
                      or previous.strip() == 'import')
        return 0.75 if start_name else 0.05
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    s = prefix.token_strings[-1]
    value = predict(s, previous, tail)
    return (doc, (tail + s)[-200:], s), float(value)

"""Approximate a quiet feature using a few local text patterns.

The main positive patterns are year-like 19/20 prefixes, Chinese 一九,
initial title-field colons, and empty HTML anchors. Numeric prefixes are stronger
after date-introducing words or opening parentheses than inside other numbers.
There are also document-start offsets for articles, code openings, letters,
digits and punctuation. Repeated middle dots and secure-URL delimiters get
negative offsets. Small word-specific responses are not memorized.
"""
import calendar
import regex as re

READS = ()
MONTHS = {name.lower() for name in calendar.month_name if name}
