def year_prefix_value(before, starts_19):
    """Use only text preceding the first two digits, never the rest of a year."""
    word = re.search(r'([a-z]+)\s*$', before, re.I)
    if word and word[1].lower() in DATE_CUES | MONTHS:
        return 0.26 if starts_19 else 0.18
    stripped = before.rstrip(' \t')
    if stripped.endswith('('):
        return 0.23 if starts_19 else 0.13
    if re.search(r'\p{Script=Han}$', stripped):
        return 0.22 if starts_19 else 0.18
    if not stripped or stripped.endswith('\n'):
        return 0.08 if starts_19 else 0.02
    if before.endswith(' '):
        return 0.19 if starts_19 else 0.08
    return 0.04 if starts_19 else 0.02


