        return 4.8
    if w == 'ч' and s == 'рез':
        return 10.4
    if w == 'пр' and s in ('ез', 'ет', 'ев'):
        return {'ез': 6.0, 'ет': 4.2, 'ев': 2.5}[s]
    if w == 'р' and s in ('ез', 'ед'):
        return 2.7 if s == 'ез' else 2.1
    if w in ('př', 'ř') and s == 'ed':
        return 4.3 if w == 'př' else 2.7
    if w == 'př' and s == 'es':
        return 3.1
    if (w, s) in (('prz', 'eds'), ('pr', 'zed')):
        return 5.7 if w == 'prz' else 3.6
    if s == 'и':
        if w.endswith('сред'):
            return 7.0
        if w in ('ред', 'уред', 'пред'):
            return 3.8
        if w.endswith('рад'):
            return 3.4
        if w.endswith('ед'):
            return 1.65
        if p.endswith(('д', 'з')):
            return 0.9
    if p == 'пред' and s in ('ы', 'ель'):
        return 4.8
    if p == 'през' and s in ('ент', 'ид'):
        return 2.8
    if w in ('qu', 'th', 'ch'):
        if s in (('ay', 'ays') if w == 'qu' else ('ai',)):
            return -6.2
    if w == 'ch':
        if token == 'IP':
            return -12.8 if previous.strip() == 'Ch' else -5.3
        if len(s) <= 3 and s.startswith((
            'ip', 'is', 'ok', 'ov', 'ong', 'um', 'ul', 'up', 'aff', 'ug',
        )):
            return -1.7
    if w == 'ч' and s in ('ай', 'ип'):
        return -4.0
    if w == 'ц' and s == 'еп':
        return -2.7
    if w == 'č' and s == 'ip':
        return -3.9
    if p == 'tr' and s == 'is':
        return -1.1
    if w.endswith('j') and s == 'edi':
        return 5.0
    if s == 'zi' and p in ('me', 'med', 'po'):
        return {'me': 4.7, 'med': 4.4, 'po': 1.35}[p]
    if w == 'z' and s[:1].isalpha() and not token[:1].isspace():
        if s.startswith('ay'):
            return -0.65
        if s.startswith(('id', 'ind', 'ed', 'ine', 'ili')):
            return 2.1
        return 0.18
    if token == 'ジ':
        if previous.endswith('レ'):
            return 5.0
        if previous.endswith(('ネ', 'ベ')):
            return 2.7
    if token and set(token) == {'⎯'}:
