import re

READS = ()


def activation(text, previous, recent, first):
    token = text.strip()
    word = token.lower()
    prev = previous.strip().lower()
    if first:
        if token == '<|endoftext|>':
            return 2.826
        if text == '//\n':  # A source file's opening comment line.
            return 5.27
        if token == 'By':  # Opening byline.
            return -1.77

    # Distinguish optional access from question-period punctuation in prose.
    if token.endswith('?.') and token[:-2] in ('', ')', ']', '()'):
        code = re.search(
            r'[{};=$]|\w\.\w|\\n|\b(?:const|let|var)\b', recent
        )
        if not code:
            return 0.2
        return 5.2 if token == '?.' else 4.5
    if token and set(token) == {'?'}:
        if '\n' in text:
            return 0.2 if len(token) >= 2 else 0.0
        if token == '??':
            code = re.search(r'[{};=$]|\w\.\w|\\n', recent)
            return 4.8 if text.startswith(' ') and code else 2.2
        return 1.5 if len(token) >= 3 else 0.06
    if token == '?:':  # Optional type/property declaration.
        return 0.89

    # Method override annotations and access-modified declarations.
    if token == '@Override':
        return -1.66
    if word == 'override':
        if previous.rstrip().endswith('@'):
            return -2.85 if token == 'Override' else -7.9
        if prev == 'public':
            return -4.1
        if prev in ('protected', 'private'):
            return -2.85
        return 0.24
    if token == 'NonNull' and previous.rstrip().endswith('@'):
        return 1.84

    # A few size-qualified visual phrases have especially negative responses.
    if word in ('picture', 'pictures'):
        if prev in ('big', 'bigger', 'biggest'):
            return -7.9 if word == 'picture' else -3.8
        return 0.12
    if word in ('screen', 'screens'):
        if prev in ('big', 'bigger', 'biggest'):
            return -5.7
        if prev in ('large', 'larger', 'largest', 'small', 'smaller', 'smallest'):
            return -1.28
        return 0.15
    if word == 'time' and prev == 'big':
        return -1.5
    if word == 'league' and prev in ('major', 'big'):
        return -0.9

    # Formatting artifacts and method-chain punctuation.
    if text.count('\u200b') >= 2:
        return 8.3 if text.startswith(' ') else 2.7
    if token == '··':
        return 0.73
    if token == '_' and prev == '_':
        return 0.2
    if token == '().':
        return 0.22
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, recent, previous = (doc, '', '') if first else carry
    text = prefix.token_strings[-1]
    value = activation(text, previous, recent, first)
    return (doc, (recent + text)[-100:], text), value

