"""A coarse, local formatting-boundary predictor.

Mixed tab/space padding, printed or escaped indentation, and visible spaces
get positive values. Ordinary indentation is near zero; a separate final
space in a run is negative. Tab padding also depends on the width of a
preceding printed line number. Special cases cover the namespace keyword
and document-initial markers, particularly the large `Title:` response.
Ordinary word-specific fluctuations and exact token-width quirks are omitted.
"""
READS = ()


def whitespace_value(text, previous, first, escaped_newline, digit_width):
    if text and not text.strip(' '):
        width = len(text)
        if first:
            return 0.4 if width == 1 else 0.7
        if escaped_newline:
            return 0.25 if width == 1 else 0.65
        if width == 1:
            if previous and not previous.strip(' \t'):
                return -0.12 if len(previous) == 1 else -0.55
            return 0.01
        if '\t' in previous and not previous.strip(' \t'):
            return 3.0
        if previous.endswith('\n'):
            return -0.02
        comment = previous.rstrip().endswith(('//', '/*', '*/', '#', '>', '|'))
        if comment or previous in ('+', '-'):
            return 0.5
        if previous.isdigit():
            return -0.1
        if previous and not previous.strip(' '):
            return 0.55
        return 0.1 if width % 4 == 3 else 0.02

    if text and not text.strip(' \t\r\n'):
        spaces = text.count(' ')
        tabs = text.count('\t')
        if '\r' in text and '\n' not in text:
            return 0.0
        if '\n' in text:
            if previous and not previous.strip(' \t'):
                return 3.0 if tabs else 2.3 if '\t' in previous else 1.3
            return 0.0
        if ' \t' in text:
            leading = len(text) - len(text.lstrip(' '))
            return 0.5 + 0.9 * min(4, leading) if leading else 2.0
        if previous.endswith(' '):
            return 3.0
        if tabs:
            number_shift = 0.25 * (min(3, max(1, digit_width)) - 2)
            if previous.rstrip().endswith(('//', '#', '>')):
                return 0.8
            if spaces:
                value = 0.65 if spaces <= 4 else 1.55 if spaces <= 12 else 2.3
                if first:
                    return value + 1.2
                return value + number_shift if previous.isdigit() else value - 0.9
            if first:
                return -0.25 if tabs == 1 else 1.3
            if previous.isdigit():
                return (0.25 if tabs == 1 else 1.0) + number_shift
            return -0.1
    if text.startswith('\t'):
        if previous.endswith(' '):
            return 2.7 + 0.4 * min(5, len(previous) - len(previous.rstrip(' ')))
        if ' \t' in previous:
            return 1.0
        return 0.05 if previous.isdigit() else -0.05
    if text == '\\x' and escaped_newline:
        return 1.3
    if text == '\\t':
        return -0.6 if first else 0.4
    if text and not text.strip(' ·') and text.count('·') >= 2:
        return min(1.1, 0.55 * text.count('·'))
    if text and '\xa0' in text and not text.strip(' \xa0'):
        if previous and not previous.strip(' ') and len(previous) >= 2:
            return 3.8 if len(previous) < 8 else 2.4
        if (text.startswith(' ') and previous.count('\xa0') >= 2
                and not previous.strip('\xa0')):
            return 2.4
        return -0.1 if text == '\xa0' else 0.5
    return 0.0


