    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail = 0, '', ''
    else:
        position, previous, tail = carry[1] + 1, carry[2], carry[3]

    if position == 0 and text == 'Title':
        value = -2.4
    elif position == 1 and previous == 'Title' and text == ':':
        value = 22.9
    elif position == 0 and text == '<|endoftext|>':
