"""Scandinavian vowel spellings and Danish/Norwegian particles.

A decaying vote from completed words' corpus frequencies estimates language.
Responses mark æ, Swedish ä, continuations after these vowels, directional
and grammatical particles, and consonant clusters. Copula-like spellings
are treated separately. Phonetic schwa receives a negative response.
Most other text stays near zero; finer word-specific effects are omitted.
"""
import math
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'de', 'nl', 'fr', 'es', 'it', 'pt', 'da', 'nb', 'sv', 'fi')


@lru_cache(maxsize=30000)
def word_vote(word):
    if len(word) < 2 or len(word) > 30:
        return None
    if not word.isascii() and any(
        'LATIN' not in unicodedata.name(char, '') for char in word
    ):
        return None
    frequencies = [zipf_frequency(word.lower(), lang) for lang in LANGUAGES]
    highest = max(frequencies)
    if highest < 4:
        # Unfamiliar names containing ø still suggest Danish or Norwegian.
        if 'ø' in word.lower():
            return tuple(0.0 if lang in ('da', 'nb') else -4.0
                         for lang in LANGUAGES)
        return None
    # Cap one word's influence, so shared words do not decide the language.
    return tuple(max(-4.0, frequency-highest) for frequency in frequencies)


def language_context(carry, document, token):
    if carry is None or carry[0] != document or token.startswith('<|'):
        scores = [0.0]*len(LANGUAGES)
        scores[0] = 3.0  # Weak English default until informative words appear.
        carry = (document, scores, '', '')
    _, scores, pending, previous = carry
    text = pending+token
    pending = ''
    scores = list(scores)
    for match in re.finditer(r'[^\W\d_]+', text):
        if match.end() == len(text):
            pending = match[0][-40:]
        else:
            vote = word_vote(match[0])
            if vote is not None:
                scores = [0.90*old+new for old, new in zip(scores, vote)]
    highest = max(scores)
    weights = [math.exp(score-highest) for score in scores]
    total = sum(weights)
    da, nb, sv = [weights[index]/total for index in (7, 8, 9)]
    # Pool the closely related Danish and Norwegian contexts.
    return (document, scores, pending, token), (da+nb+sv, da+nb, sv), previous


