            value += 3.293*dan_no
        if word == 'der':
            value += 7.943*dan_no
        if word in ('de', 'da', 'hans', 'dem'):
            value += 1.425*dan_no
        if word in ('om', 'over', 'efter', 'henne'):
            value += 3.623*dan_no
        if word == 'hvad':
            value += 4.706*dan_no
        if word == 'blev':
            value += 3.227*dan_no
    if re.search(r'(?:[lnr]d|d[lr])$', word):
        value += 1.626*dan_no
    if re.search(r'[dklrfn]s$', word):
        value += 1.142*dan_no
    if re.search(r'([bcdfghjklmnpqrstvwxz])\1', word):
        value += 0.313*dan_no
    if len(word) == 1 and word in 'bcdfghjklmnpqrstvwxz':
        value += 0.424*north
    if copula:
        value -= 0.446*swedish
    if word in ('være', 'været'):
        value -= 0.473*dan_no
    if word == 'ə':
        value -= 3.597
    return carry, float(value)

programs.haiku:
"""Danish-context word-piece rule for layers.1.mlp.down_proj component 2026.

The component fires on a handful of word pieces that are distinctive of Danish
and Norwegian text, and only when the text around them is Scandinavian:

- the letter æ inside a short word piece ("hj|æ|lpe", "g|æ|lder", "væ|rd");
- Danish particles that are whole words: "af" (of), "ud", "op", "ind", "end";
- a few other Danish words: "at", "der", "om", "hvad", "blev";
- Swedish ä pieces ("hj|ä|lp"), weaker.

A context score says how Scandinavian the last 60 tokens are: the share of
Danish, Norwegian or Swedish function words, or words with æ, ø or å, among
them, saturating at 5 such words. Outside Scandinavian text the rule predicts
(almost) 0, which is what keeps it from firing on English, German or code.
"""
READS = ()

# Words that are distinctly Danish/Norwegian/Swedish (not also English or German).
SCANDINAVIAN = {"og", "ikke", "som", "på", "jeg", "med", "til", "af", "hvor", "kan",
                "også", "fra", "sig", "blev", "hun", "han", "vil", "når", "selv", "eller",
                "och", "är", "att", "inte", "för", "till", "av", "ett", "från", "när", "hon"}
# Whole-word tokens that are Danish particles, and their activation at full context.
PARTICLES = {"af": 7.0, "afs": 7.0, "ud": 5.0, "op": 5.0, "opp": 4.0, "ind": 5.0,
             "end": 5.0, "mod": 4.0}
MINOR = {"der": 2.0, "at": 3.0, "om": 2.0, "hvad": 4.0, "over": 2.0, "blev": 3.0,
         "efter": 3.0, "her": 2.0}
WINDOW = 60   # tokens of context looked at
FULL = 5      # Scandinavian words in the window that count as fully Scandinavian


def scandinavian(word):
    return word in SCANDINAVIAN or any(c in word for c in "æøå")


def step(carry, prefix, upstream):
    recent = carry if carry is not None else []
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        recent = []  # a new document: forget the language of the old one
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    hits = sum(1 for w in recent if scandinavian(w))
    context = min(1.0, hits / FULL)
    whole = text.startswith(" ")  # a token that begins a word
    if "æ" in text and len(word) <= 4:
        value = 4.0 + 4.0 * context
    elif whole and word in PARTICLES:
        value = PARTICLES[word] * context
    elif whole and word in MINOR:
        value = MINOR[word] * context
    elif "ä" in text and len(word) <= 4:
        value = 2.0 * context
    else:
        value = 0.0
    return (recent + [word])[-WINDOW:], value

programs.sol:
"""An opening-token pulse, with smaller responses to expression punctuation.

A document begins with a large negative value.  Its size depends on broad token
shapes: words without a leading space are stronger than punctuation or digits.
An unchanged repeated opening token keeps the pulse.  Later, colons in object
keys and plus/minus signs after mathematical operands give positive values.
"""
import re
import regex

READS = ()

# Closed-class words: linking words and auxiliary verbs, not content words.
LINKS = frozenset("""
    of to in on at for with by from about into onto upon under over across
    through between during against without within as than
    and or if that while because although when unless but whether though
    whereas so is are was were be been being am do does did has have had
    can could will would shall should may might must
""".split())
ARTICLES = frozenset(("a", "an", "the"))


def opening_value(token):
    word = token.strip()
    if token.startswith('<|'):
        return -7.3
    if not word:
        if '\n' in token or '\r' in token:
            return -5.9
        return -3.86 if token == ' ' else -9.9
    if word.isdecimal():
        return -7.7
    if regex.search(r'\p{Script=Han}', word):
        return -7.2
    if word.isalpha():
        if not word.isascii():
            return -8.7
        if word.lower() in ARTICLES:
            return -10.3 if token.startswith(' ') else -11.8
        if token.startswith(' '):
            if word.lower() in LINKS:
                return -7.7
            if len(word) == 1 and word != 'I':
                return -6.5
            return -9.6 if word[0].isupper() else -9.0
        return -10.9 if word[0].isupper() else -9.9
    if word.startswith('_') and any(c.isalpha() for c in word):
        return -7.0
    if all(not c.isalnum() for c in word):
        if '\n' in token:
            return -5.5
        if any(c in '#*|;&' for c in word):
            return -10.8
        if len(set(word)) == 1 and len(word) > 1:
            return -10.0
        return -6.3
    return -8.6


def expression_value(token, before):
    mark = token.strip()
    if '\n' in token or '\r' in token:
        return 0.0
    if mark.endswith(':') and not any(c.isalnum() for c in mark):
        if '"' in mark:
            return 1.4
        if "'" in mark:
            return 1.0
        # An identifier in an object, parameter list, or type annotation.
        if mark == ':' and re.search(r'[\w\'\"]$', before.rstrip()):
            if '{' in before or re.search(r'\b(def|fn|let|const)\b', before):
                return 0.7
        return 0.04
    if regex.fullmatch(r'[)}\]]?[+−-]\\?', mark):
        previous = before.rstrip()
        operand = regex.search(r'(\p{N}|[)\]}]|\b\p{L})$', previous)
        if operand:
            math_context = '=' in before or '^' in before
            if token in ('+', '-'):
                return 0.4 if math_context else 0.0
            return 1.0 if math_context else 0.65
    if mark == '=>':
        return 0.32
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        value = opening_value(token)
        return (document, token, True, token[-160:]), value
    _, opening, repeated, before = carry
    repeated = repeated and token == opening
    value = opening_value(token) if repeated else expression_value(token, before)
    return (document, opening, repeated, (before + token)[-160:]), value

"""A rough lexical/grammatical detector centered on Chinese 所.

Place/office nouns ending in 所 get a positive pulse; nominalizing 所 and
its Han continuations get negative pulses. 所以 ('therefore'), 所有 ('all'
or ownership), and 有所 ('somewhat') are treated separately. 相 relational
phrases have a weaker negative response. Secondary rules cover Korean 소,
Japanese ソ連, copyright formulas, and document/source-code beginnings.
These are calibrated averages, not a reconstruction of contextual variation.
"""
from functools import lru_cache
import cedict
import regex

READS = ()
HAN = regex.compile(r"^\p{Script=Han}+$")
PLACE = regex.compile(
    r"\b(office|institute|station|exchange|clinic|toilet|clubhouse|place|location)\b"
)


@lru_cache(maxsize=2048)
def place_ending(text):
    """Look up short noun compounds, rather than list institution names."""
    return any(
        PLACE.search(gloss)
        for length in (2, 3, 4)
        for gloss in cedict.glosses(text[-length:])
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new = carry is None or carry[0] != doc
    previous, tail = ("", b"") if new else carry[1:]
    before = tail.decode("utf-8", "ignore")
    joined = tail + prefix.token_bytes[-1]
    # Recognize characters completed across byte-token boundaries.
    token = joined.decode("utf-8", "ignore")[len(before):]
    word = token.strip()
    value = 0.0

    if new:
        value = 0.1 if not word or word[0].islower() else 0.2
        if word in {"package", "from", "import", "export"}:
            value = 1.3
        if token == "//\n":
            value = -3.27

    if word.startswith("所以"):
        value = -0.07
    elif word.startswith("所有"):
        ownership = any(x in before[-20:] for x in ("版权", "版權", "归", "歸"))
        value = -2.4 if ownership else -0.5
    elif word == "有所":
        value = 0.6
    elif word.endswith("所") and place_ending(before + token):
        value = 0.4
    elif word == "所":
        value = -0.22
    elif word.startswith("所") and len(word) > 1:
        value = -3.0
    elif before.endswith("所") and HAN.fullmatch(word):
        if not place_ending(before) and word not in {"的", "之", "长", "長", "副"}:
            if before.endswith("有所") and len(word) > 1:
                value = -0.2
            else:
                value = -4.0 if len(word) == 1 else -1.4

    if previous in {"相", "相互", "互相"} and HAN.fullmatch(word):
        value = -0.5
    elif word.startswith("相") and len(word) > 1:
        lexical = ("相信", "相片", "相机", "相機", "相应", "相應")
        if not word.startswith(lexical):
            with_another = any(x in before[-16:] for x in "与與和同")
            value = -0.4 if with_another else -0.2

    # The syllable 'so', especially the compounds 소속 and 소지.
    if word == "소":
        value = -1.55 if token.startswith(" ") else -0.45
        if previous.strip() == "소":
            value = -3.5
    elif previous.strip() == "소" and word in {"속", "지"}:
        value = -5.8
    elif word == "속":
        value = -0.5
    elif previous == "ソ" and word == "連":
        value = -1.4

    if previous.strip().lower() == "rights" and word.lower() == "reserved":
        value = -2.3 if word[0].isupper() else -0.9

    return (doc, token, joined[-64:]), value

"""A sparse lexical signal for facilities, facilitation and ease.

Give negative values to the facil- and flexib- families and feasibility.
Word fragments matter: completing a split stem can fire more strongly
than a whole word. Recognize Chinese/Japanese facility compounds and
implementation characters too, with the strongest response on the second
character of 施設/設施. Return zero outside this core vocabulary.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, previous = '', ''
    else:
        _, word, previous = carry
    token = prefix.token_strings[-1]
    lower = token.lower()
    word_now = re.split(r'[^\w]', word + lower)[-1][-48:]
    piece = lower.isalpha() and bool(word)
    value = 0.0

    if re.search(r'facilit(?:y|ies)', lower):
        value = -5.0
    elif 'facilit' in lower:
        value = -4.4 if lower.strip().endswith('facilit') else -3.3
    elif 'facil' in lower:
        value = -0.9 if lower.strip().endswith('facile') else -2.0
    elif piece and 'facil' in word_now:
        if 'facil' not in word:
            value = -6.0
        else:
            value = -4.2 if lower.startswith('it') else -1.0
    elif 'flexib' in lower:
        value = -1.3 if 'ility' in lower else -2.0
    elif piece and 'flexib' in word_now:
        value = -3.6 if 'flexib' not in word else -0.3
    elif lower.strip() == 'feasibility':
        value = -1.8
    elif piece and re.search(r'feasib', word_now) and lower.startswith('ib'):
        value = -3.4 if previous.lower().strip() == 'as' else -1.0

    if token == '施':
        value = -9.5 if previous.endswith('設') else -3.2
        if previous.endswith(('実', '实')):
            value = -2.4
    elif token == '設' and previous.endswith('施'):
        value = -7.2
    elif token == '设施':
        value = -3.0
    elif token == '实施':
        value = -1.2

    return (doc, word_now, token), value

programs.haiku:
"""Facility-family detector (v8).

Tracks the Latin-letter word being spelled (reset at any non-letter) and marks
pieces of the facility / flexibility word family, which the component reads
as strongly negative. Other positions are predicted 0.
"""
READS = ()
# stems matched inside the current word; more specific stems are checked first
NEG = {"facilit": -4.3, "fasilit": -6.0, "facil": -1.7, "flexib": -1.9, "felicit": -4.0}
CJK = {"施": -3.8, "設": -2.7}           # facility characters 施 (shi) and 設 (setsu)
CJK_WORDS = {"设施": -2.2, "施設": -2.2, "設施": -2.2}  # 設施 / 施設 / 设施 compounds
def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    cur = carry[1] if carry is not None and carry[0] == doc else ""
    s = prefix.token_strings[-1]
    for ch in s:
        cur = cur + ch.lower() if ch.isascii() and ch.isalpha() else ""
    for w, v in CJK_WORDS.items():
        if w in s:
            return (doc, cur), v
    if s in CJK:
        return (doc, cur), CJK[s]
    for stem, v in NEG.items():
        if stem in cur:
            return (doc, cur), v
    return (doc, cur), 0.0

programs.sol:
"""Approximate a sparse local spelling signal, not a semantic classifier.

The rules cover standalone Japanese ta (stronger after an a/u/o hiragana),
突 (thrust/sudden), a URL delimiter, and source-file opening markers. Other
activations are left at zero. This is a partial account of a multilingual
spelling signal, not a semantic classifier; the ta rule is only a rough
distinction from past-tense endings.
"""
from anyascii import anyascii
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, age, japanese = '', 0, False
    else:
        _, previous, age, japanese = carry

    token = prefix.token_strings[-1]
    if previous == '<|endoftext|>':
        age, japanese = 0, False
    value = 0.0

    if token == 'た' and len(previous) == 1:
        last = previous[-1]
        name = unicodedata.name(last, '')
        if name.startswith('HIRAGANA LETTER'):
            sound = anyascii(last).lower()
            # Stem-internal ta, rather than the usual i/e + past-tense ta.
            if sound.endswith(('a', 'u', 'o')) and last != 'っ':
                value = 1.4
    elif token == 'タ':
        value = 0.35
    elif token == '突':
        value = 4.7 if japanese else 2.3
    elif token == '://':
        value = 0.19
    elif token == 'php' and previous == '<?':
        value = 1.26 if age <= 1 else 0.25
    elif token == 'filename' and previous == '<' and age <= 1:
        value = 1.79
    elif token == 'package' and age == 0:
        value = 0.52

    if not japanese and any(
        'HIRAGANA' in unicodedata.name(c, '') for c in token
    ):
        japanese = True
    return (doc, token, age + 1, japanese), value

programs.haiku:
"""layers.1.mlp.down_proj:2030, a weak word-piece feature.

What it does: it is nearly silent, but its largest responses fall on pieces of a
word that begin right after the previous piece with no space, i.e. word-internal
subword or character fragments (a CJK character inside a word, a Latin or Cyrillic
subword, a UTF-8 byte fragment). Those pieces carry about half of the activation's
energy, with about 2.5 times the RMS of other tokens. Their sign is set mostly by
the token itself, and the simple rules here do not capture it.

What this program predicts: on a word-internal piece, a small value whose sign
follows the script that dominates the document so far (CJK, kana and Hangul text
lean positive; Cyrillic, Arabic and Thai text lean negative); zero elsewhere.
The constants are the mean activation per script on such pieces in training text.
"""

READS = ()

# Mean activation on word-internal pieces, by the document's dominant script.
DOMAIN_VALUE = {"cjk": 0.003, "kana": 0.003, "hangul": 0.008,
                "cyr": -0.004, "arab": -0.037, "thai": -0.046}


def script_of(ch):
    o = ord(ch)
    if o < 128:
        return "latin" if ch.isalpha() else None
    if 0x4E00 <= o <= 0x9FFF or 0x3400 <= o <= 0x4DBF:
        return "cjk"
    if 0x3040 <= o <= 0x30FF:
        return "kana"
    if 0xAC00 <= o <= 0xD7AF:
        return "hangul"
    if 0x0400 <= o <= 0x04FF:
        return "cyr"
    if 0x0600 <= o <= 0x06FF:
        return "arab"
    if 0x0E00 <= o <= 0x0E7F:
        return "thai"
    if 0x00C0 <= o <= 0x024F:
        return "latin"
    return None


def word_internal(token, previous):
    """A piece that starts a letter or non-ASCII character and follows a piece that
    ends one, so no space separates them."""
    if not token or token[0].isspace() or not (token[0].isalpha() or ord(token[0]) > 127):
        return False
    return bool(previous) and not previous[-1].isspace() and (
        previous[-1].isalnum() or ord(previous[-1]) > 127)


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids
    if t == 0 or doc[t] != doc[t - 1]:
        counts = {}
        previous = ""
    else:
        counts = dict(carry[0]) if carry else {}
        previous = prefix.token_strings[t - 1]
    token = prefix.token_strings[t]
    for ch in token:
        s = script_of(ch)
        if s:
            counts[s] = counts.get(s, 0) + 1
    if t == 0 or doc[t] != doc[t - 1]:
        previous = ""
    value = 0.0
    if sum(counts.values()) >= 5 and word_internal(token, previous):
        dominant = max(counts, key=counts.get)
        value = DOMAIN_VALUE.get(dominant, 0.0)
    return (counts, None), value

programs.sol:
"""A lexical detector for 質/质 (quality, substance) and related written forms.

The character on its own gets a much stronger response than a whole word
containing it. Vietnamese chất and Korean 질 are corresponding readings.
Recent Japanese kana weakens the response to 質. A coarse orthographic
first-token correction is added at each document boundary. This is not a
general detector of things that have good quality. It also gives weaker
responses to placement/making forms, and completes split UTF-8 characters.
"""
from functools import lru_cache
import codecs
import regex

READS = ()

@lru_cache(maxsize=32768)
def lexical(text, japanese):
    s = text.strip()
    if s == '质':
        return 5.2
    if s == '質':
        return 3.7 if japanese else 5.6
    # Whole words containing the quality/substance character are weaker.
    if any(c in s for c in '质質'):
        if s.startswith(('质', '質')):
            return 0.6
        if s.startswith(('优', '優')):
            return 0.6
        if s.startswith(('品', '素')):
            return 1.3
        # Temperament (气质) and bodily constitution (体质).
        if len(s) == 2 and s[0] in '气氣体體':
            return 3.8
        return 2.6 if len(s) == 2 else 1.3
    # Related placement/configuration and making/customization forms.
    if s in ('置', '配置', '前置'):
        return 1.4
    if s in ('制', '製'):
        return 0.55
    if s in ('定制', '訂製'):
        return 1.0
    if s in ('制造', '製造'):
        return 0.65
    # Vietnamese readings/ending, and Korean 'jil'.
    if s == 'chất':
        return 3.5
    if s == 'chế':
        return 1.5
    if s == 'ất':
        return 1.0
    if s == '질':
        return 1.8
    return 0.0


@lru_cache(maxsize=32768)
def beginning_offset(text):
    """A small first-token correction based on writing system and token shape."""
    s = text.strip()
    if text.startswith('<|'):
        return -0.39
    if not s:
        return -0.11
    if s.isdigit():
        return 0.03
    if s.isascii() and s.isalpha():
        if text[0].isspace():
            return -0.06
        return -0.24 if len(s) == 1 else -0.31
    if s.isascii():
        if s.startswith(('//', '/*', '<?', '<!')):
            return -0.75
        return 0.06
    return -0.11 if regex.search(r'\p{Script=Han}', s) else 0.01


_KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')

@lru_cache(maxsize=32768)
def has_kana(text):
    return bool(_KANA.search(text))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    beginning = carry is None or carry[0] != doc
    if beginning:
        age, tail = 100, b''
    else:
        _, age, tail = carry
    # Keep only unfinished UTF-8 bytes, not earlier complete characters.
    data = tail + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(data, 'replace', False)
    value = lexical(text, age < 30)
    if beginning:
        value += beginning_offset(text)
    age = 0 if has_kana(text) else min(age + 1, 100)
    return (doc, age, data[used:]), value

programs.haiku:
"""Component layers.1.mlp.down_proj:2032, a detector for the morpheme 質/质.

The morpheme means "quality, nature, substance" (Japanese and traditional 質, simplified 质).
Almost everywhere the component is near zero. It fires on the morpheme itself:

- the bare character 質 or 质 (良質, 質地, 质 in 腐烂变质): strongest, about 4.5;
- a word that ends in it (气质, 本质, 木质, 性质, 物质, 品质): about 2.5;
- the morpheme inside a longer word (质量, 高质量, 优质): weak, about 0.5;
- its Vietnamese and Korean equivalents chất, 질 and chế: about 2.5;
- the "set / make" morphemes 置, 製, 制, 配置, 定制, 制造: about 1.0.

A document that starts in the middle of a row (after <|endoftext|>) has a negative first
token, about -0.3; a row's very first token is about 0. Nothing else is predicted.
Only the current token and the document ids are read, so the program is stateless.
"""

READS = ()

QUALITY = ("質", "质")
FOREIGN = ("chất", "질", "chế")
SET_MAKE = ("置", "製", "制", "配置", "定制", "制造", "前置")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    row_start = len(prefix.token_ids) == 1
    new_document = row_start or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_document:
        value = 0.0 if row_start else -0.3
    elif token in QUALITY:
        value = 4.5
    elif token in FOREIGN:
        value = 2.5
    elif token in SET_MAKE:
        value = 1.0
    elif token[-1:] in QUALITY:
        value = 2.5
    elif "质" in token or "質" in token:
        value = 0.5
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Coarse opening-token activation, not a word-by-word lookup.

Short, unspaced alphabetic openings tend to be positive; longer tokens tend
lower. Capitalization, script, and a few grammatical/punctuation classes
refine this estimate. After the opening token changes, predict zero.
An uninterrupted repetition of the opening token keeps its opening value.
This leaves substantial word-specific variation unexplained.
"""
import regex

READS = ()
PRONOUNS = set('i you he she it we they me him her us them'.split())
CONJUNCTIONS = set('and or but nor yet so if'.split())


def opening(text):
    word = text.strip()
    if not word:
        return 0.11 + 0.38 * ('\n' in text) - 0.10 * min(len(text), 8)
    if text.startswith('<|'):
        return -0.19
    if word.isalpha():
        if regex.fullmatch(r'\p{Latin}+', word):
            bare = not text[0].isspace()
            return (0.20 - 0.12 * min(len(word), 10)
                    + 0.63 * (bare and word[0].isupper())
                    + 0.92 * (bare and len(word) == 1)
                    + 0.44 * (word.lower() in PRONOUNS)
                    + 0.49 * (word.lower() in CONJUNCTIONS))
        if regex.search(r'\p{Han}', word):
            return -0.01
        if regex.fullmatch(r'[\p{Cyrillic}\p{Greek}]+', word):
            return (-0.08 + 0.80 * word[0].isupper()
                    + 0.57 * (len(word) == 1))
        return 0.43
    if word.isnumeric():
        return -0.04
    if all(c in ',，' for c in word):
        return 0.37
    if all(c in '#/' for c in word):
        return -0.51
    if len(word) > 1 and all(c == '·' for c in word):
        return 3.65  # Repeated middle-dot separators.
    return -0.10 + 0.18 * ('�' in word)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening(prefix.token_strings[-1])
        carry = (doc, token, value, True)
    else:
        doc, first, value, unchanged = carry
        unchanged = unchanged and token == first
        carry = (doc, first, value, unchanged)
        if not unchanged:
            value = 0.0
    return carry, float(value)

