"""Draft A."""
READS = ()

NAMES = frozenset("John Mary James Robert Michael William David Richard Joseph Thomas Charles Daniel Mark Paul George Brian Gary Jim Jimmy Danny Mike Ron Dave Joe Jane Karen Jennifer Anthony Christopher Arthur Stan Ian Ray Frank Edward Karen Sarah Susan Linda Patricia Barbara Nancy Lisa Ashley Emily Jessica Maria".split())
PRONOUNS = frozenset("I You He She We They There Who What How When Where Why This".split())
FUNCTION = frozenset("the a an of to in on at for by from with and or but as is was are be do does did has have had will would can not if so than that which".split())

def step(carry, prefix, upstream):
    d = prefix.document_ids
    if len(d) > 1 and d[-1] == d[-2]:
        return carry, 0.0
    s = prefix.token_strings[-1]
    w = s.strip()
    lw = w.lower()
    if not w or not any(c.isalnum() for c in w):
        v = 0.0
    elif len(w) == 1 and w.isalpha():
        v = 1.6 if w.isupper() else 0.5
    elif s.startswith(" "):
        v = -0.3 if lw in FUNCTION else -0.4
    elif w in NAMES:
        v = -1.8
    elif lw in PRONOUNS:
        v = 0.8
    elif not w.isalpha():
        v = 0.0
    elif w[0].isupper():
        v = 0.8 if len(w) <= 4 else (0.0 if len(w) <= 8 else -0.8)
