programs.sol:
"""A partial lexical/contextual approximation of a second-person signal.

Predict positive values for 'you', smaller values for possessives and
reflexives, and values for the listed second-person forms in other languages.
The preceding token boosts 'you' after clause openers, lowers it after
auxiliaries and selected verbs, and reverses it after 'thank'. Document
starts have a negative baseline; middle-dot leader runs are strongly
negative. Unrecognized tokens elsewhere receive zero. Context resets at
each document boundary.
"""
READS = ()

CLAUSE_STARTERS = {'if', 'when', 'because', 'until', 'once', 'but'}
MODALS = {'can', 'could', 'will', 'would', 'shall', 'should', 'may', 'might'}
OBJECT_VERBS = {'help', 'assist', 'give', 'gives', 'make', 'makes',
                'get', 'gets', 'let', 'tell', 'tells', 'see'}

# Lexical forms of 'you' and 'your', not a general translation rule.
OTHER_FORMS = {
    'your': 1.02, 'yours': 0.64, 'yourself': 0.40, 'yourselves': 0.40,
    'vous': 0.95, 'votre': 0.68, 'vos': 0.24,
    'você': 0.96, 'usted': 0.68, 'bạn': 0.78,
    'вам': 0.55, 'вас': 0.55, 'ваш': 0.54,
    '你': 0.95, '妳': 0.95, '您': 1.10,
    '你们': 0.88, '你們': 0.88, '你的': 0.70, '您的': 0.96,
    '如果你': 0.87, '如果您': 1.10, '让你': 0.61,
    'あなた': 0.83,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous = '' if fresh else carry[1]
    before = previous.strip().lower()

    value = OTHER_FORMS.get(lower, 0.0)
    if lower == 'you':
        if fresh:
            value = -0.63
        elif before == 'thank':
            value = -1.8 if previous == 'Thank' else (
                -1.3 if previous.strip() == 'Thank' else -0.6)
        elif before in CLAUSE_STARTERS:
            value = 1.80
        elif before in MODALS or before in {'do', 'does'}:
            value = 1.13
        elif before in {'are', 'were', 'am', 'is', 'was'}:
            value = 0.95
        elif before in {'have', 'has', 'had', 'did'}:
            value = 1.30
        elif before in OBJECT_VERBS:
            value = 1.18
        elif before in {'to', 'for', 'of', 'than', 'how', 'then'}:
            value = 1.32
        elif before in {'and', 'or', ','}:
            value = 1.63
        else:
            value = 1.50 if word.islower() else 1.72
    elif lower == 'ye':
        boundary = token[:1].isspace() or not previous[-1:].isalpha()
        value = 1.1 if boundary else 0.35
    elif word and set(word) == {'·'} and set(previous.strip()) == {'·'}:
        value = -3.75
    elif fresh:
        value = -0.19

    return (doc, token), value

programs.haiku:
"""Second-person pronoun detector.

Fires on the word "you" (and "your", and their translations), at the token itself.
Strength depends on the word before it:
  - "thank you": strongly negative
  - "you" after a verb, auxiliary or preposition (do you, can you, help you, to you): medium
  - "you" starting a clause (if you, when you, ", you", sentence start): strong
"""

READS = ()

YOU = {" you", "you", " You", "You", " YOU", "YOU"}
YOUR = {" your", "your", " Your", "Your", " YOUR", "YOUR"}
OTHER_YOU = {"你", "您", " você", " ya", "ya"}
# words before "you" that make it an object or verb-complement
AFTER_VERB = {"do", "does", "can", "could", "will", "would", "are", "have", "help",
              "to", "for", "of", "with", "tell", "let", "how", "like", "are", "is"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if tok in YOU:
        if prev == "thank":
            return None, -1.5
        if prev in AFTER_VERB:
            return None, 1.1
        return None, 1.7
    if tok in YOUR or tok in OTHER_YOU:
        return None, 1.0
    return None, 0.0

programs.sol:
"""A sparse recognizer for conventional web and markup spellings.

Predict large responses on localhost/example addresses, LaTeX environment
braces, and selected HTML/XML names. Also recognize a few source-document
conventions: @file, &copy;, and standard source/web directory paths. These
are local spelling rules, not a parser. Weak, widespread background responses are left at zero.
The text buffer resets at document boundaries.
"""
import re

READS = ()

URL_HOSTS = {
    'localhost': 4.8,
    'example': 4.8,
    'github': 1.4,
    'facebook': 0.7,
    'html': 2.4,
}
OPEN_TAGS = {
    'html': 2.5,
    'pre': 2.6,
    'title': 2.6,
    'style': 1.6,
    'link': 1.2,
    'b': 0.8,
    'p': 1.2,
    'br': 1.3,
    'hr': 0.9,
    'h': 1.0,
    'returns': 2.5,
    'value': 1.6,
}
CLOSE_TAGS = {
    'html': 2.5,
    'pre': 1.2,
    'returns': 0.45,
    'p': 0.2,
    'table': -0.7,
    'tr': -0.35,
}
PLACEHOLDERS = {'file', 'filename', 'nil', 'your', 'host'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if before.endswith('://'):
        value = URL_HOSTS.get(s, 0.0)
    elif s.strip() == 'localhost':
        value = 3.4
    elif s == ':' and before.endswith('localhost'):
        value = 2.2
    elif s == '.example' and re.search(r'\bcom$', before):
        value = 8.1 if before == 'package com' else 5.6
    elif s == '.example' and before.endswith('www'):
        value = 3.6
    elif s == '@example' or (s == 'example' and before.endswith('@')):
        value = 2.0
    elif s == '.lastname' and before.endswith('firstname'):
        value = 2.5
    elif s == 'file' and before.endswith('@'):
        value = 3.0
    elif s == 'overview' and before.endswith('@file'):
        value = 1.5
    elif s == 'copy' and before.endswith(('&', '<')):
        value = 2.6
    elif s == '{' and re.search(r'\\(?:begin|end)$', before):
        value = 1.5
    elif s == 'string' and before.endswith('"<'):
        value = 0.7
    elif before.endswith('</'):
        value = CLOSE_TAGS.get(s, 0.0)
    elif before.endswith('<'):
        value = OPEN_TAGS.get(s, 1.0 if s in PLACEHOLDERS else 0.0)
        if s == 'p' and re.search(r'(?:\*|///)\s*<$', before):
            value = 2.0
    elif s.startswith('<'):
        value = 0.6 * OPEN_TAGS.get(s[1:], 0.0)
    elif len(s) == 1 and s in '123456' and before.endswith('<h'):
        value = 1.2
    elif s == ' name' and before.endswith('<param'):
        value = 1.05
    elif s == '/local' and before.endswith('/usr'):
        value = 1.2
    elif s == '/test' and before.endswith('src'):
        value = 0.7
    elif s == '/index' and before.endswith('/src'):
        value = 0.5
    elif s == '/www' and before.endswith('/var'):
        value = 0.6
    return (doc, (before + s)[-64:]), value

programs.haiku:
"""Layer-1 MLP feature: stock host names and markup names.

Fires on a token that names a host, a tag or a LaTeX environment, in the few
contexts where this component reliably responds:

  * 'localhost' anywhere (http://localhost:3000), strongest after a URL scheme;
  * placeholder domains and mail names: 'example' or 'lastname' after a scheme, '@', a
    dot or 'com' (http://example.com, import com.example.app, firstname.lastname), and the
    tokens '@example' and '.lastname' on their own (user@example.org);
  * the Chinese word for 'web address' (网址);
  * 'github' right after 'https://';
  * the '{' that opens a LaTeX \\begin{...} or \\end{...};
  * 'local' in a path such as /usr/local;
  * an HTML/XML tag name right after an opening '<' (<p>, <pre>, <br>, <returns>, ...),
    a moderate response;
  * a weak, constant bump on the first token of each document.

Everything else predicts 0. The values are the typical activation in each case.
"""
READS = ()

PLACEHOLDER_HOSTS = {"example", ".example", "lastname", ".lastname"}
PLACEHOLDER_DOMAINS = {"@example", ".lastname"}
HOST_OPENERS = {"://", "@", ".", "com", "localhost"}
LATEX_ENVIRONMENT_WORDS = {"begin", "end"}
HTML_TAGS = {
    "p", "pre", "br", "hr", "b", "i", "h", "h1", "h2", "h3", "h4", "div", "span", "a",
    "table", "tr", "td", "th", "ul", "li", "ol", "title", "style", "script", "link", "meta",
    "value", "returns", "param", "summary", "img", "strong", "em", "tt", "big", "small",
    "code", "html", "body", "head", "file", "filename", "list", "button", "label", "form",
}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    if len(prefix) == 1:
        prev, new_document = None, True
    else:
        prev = prefix.token_strings[-2].strip()
        new_document = prefix.document_ids[-1] != prefix.document_ids[-2]

    if cur == "localhost":
        return None, 4.5
    if cur in PLACEHOLDER_HOSTS and prev in HOST_OPENERS:
        return None, 4.8
    if cur in PLACEHOLDER_DOMAINS:
        return None, 2.5
    if cur == "网址":
        return None, 1.6
    if cur == "github" and prev == "://":
        return None, 1.3
    if cur == "{" and prev in LATEX_ENVIRONMENT_WORDS:
        return None, 1.4
    if cur == "/local":
        return None, 1.2
    if prev == "<" and cur in HTML_TAGS:
        return None, 0.6
    if new_document:
        return None, 0.14
    return None, 0.0

programs.sol:
"""Approximate a detector of indices and annotations on mathematical symbols.

Subscripts give large negative values; powers and number suffixes give
smaller ones. The clues are TeX markers, HTML tags, Unicode character names,
and adjacency to short variable names. These dominate active training
examples. Long base names, ordinary words, and byte escapes are treated
conservatively. Strengths approximate training averages. Two positive
exceptions recognize HTML target="_blank" and 'all' after an underscore.
Only a short byte tail and an unfinished annotation are carried forward.
"""
import re
import unicodedata as ud

READS = ()
GREEK = set('alpha beta gamma delta epsilon zeta eta theta iota kappa '
            'lambda mu nu xi omicron pi rho sigma tau upsilon phi chi '
            'psi omega varphi vartheta varepsilon varrho varsigma'.split())
FUNCTIONS = set('sin cos tan cot sec csc sinh cosh tanh log ln exp '
                'lim sum prod'.split())
SHORT_FUNCTION_WORDS = set(
    'a an as at am be by do go he if in is it me my no of on or so to '
    'up us we re ve ll'.split())


def greek(c):
    return ('GREEK' in ud.name(c, '') or c == 'µ') and c.isalpha()


def base(tail):
    """The isolated symbol or short name immediately before an annotation."""
    m = re.search(r'([A-Za-z]+)$', tail)
    if m:
        name = m[1]
        before = tail[m.start()-1] if m.start() else ''
        if before and before.isalpha():
            return ''  # not a one-letter suffix of an accented word
        if name in ('n', 'r', 't', 'x') and before == '\\':
            return ''  # escaped whitespace or a byte escape, not an index base
        if tail.endswith('0x') or before in ("'", '’'):
            return ''
        if (re.search(r'(?<![A-Za-z0-9])[A-Fa-f0-9]{4,}$', tail)
                and any(c.isdigit() for c in tail[-4:])):
            return ''  # a hexadecimal identifier
        if name.lower() in GREEK:
            return 'greek' if before == '\\' else 'greek_name'
        if name.lower() in FUNCTIONS:
            return 'function'
        if len(name) == 1:
            if m.start() and tail[m.start()-1] == '_':
                return ''
            return 'function_word' if name in ('a', 'A', 'I') else 'single'
        if len(name) == 2:
            return 'short'
    if tail and greek(tail[-1]) and (len(tail) < 2 or not tail[-2].isalpha()):
        return 'greek'
    if tail.endswith('}'):
        return 'brace'
    return ''


def predict(s, raw, tail, pending, previous_bytes=b''):
    b = base(tail)
    spaced = base(tail.rstrip())
    compact = s.lstrip(' }')
    if s == 'blank' and re.search(r'target\s*=.*["\']_$', tail):
        return 8.34, ''
    if s == 'all' and tail.endswith('_'):
        return 0.64, ''
    # Two trailing bytes cannot contain an old, complete subscript character.
    joined = (previous_bytes[-2:] + raw).decode('utf-8', 'ignore')
    if any(ud.name(c, '').startswith('SUBSCRIPT') for c in joined):
        return (-2.38 if b or spaced or pending == 'unicode'
                else -1.31), ''
    if raw == b'\xe2\x82':
        return -0.94, 'unicode'
    if s and ud.name(s[0], '').startswith('SUPERSCRIPT'):
        return (-0.93 if s[0] == '²' else -0.58), ''
    if s in ('′', '″', '⁻', '⁺') and b:
        return -0.9, ''
    if tail.endswith('<sub') or tail.endswith('<sup'):
        return (-2.41 if s == '>' else -6.36), ''
    if tail.endswith('<sub>') and not s.startswith('<'):
        return -3.5, ''
    # Explicit subscript: the marker, its opening brace, and its argument.
    subscript_base = spaced in (
        'single', 'function_word', 'greek', 'greek_name', 'brace', 'function')
    if compact.startswith('_') and (subscript_base or
            spaced == 'short' and ('\\' in tail or '$' in tail)):
        suffix = compact[1:]
        if not suffix:
            return -1.05, 'subscript'
        if suffix.startswith('{'):
            return -2.37, 'subscript'
        if len(suffix) == 1 and suffix.isalpha():
            return -3.11, ''
        if suffix.startswith('\\'):
            return -2.35, 'subscript_name'
        if suffix.lower() in GREEK:
            return -3.11, ''
        return -0.47, ''
    # Exponents are weaker responses than subscripts.
    if compact.startswith('^') and spaced:
        suffix = compact[1:]
        return (-0.89 if suffix.startswith('{') else -0.51), (
            'power' if suffix in ('', '{', '-', '{-', '(') else '')
    if pending == 'subscript':
        if not s.strip():
            return 0.0, pending
        if s.startswith('{'):
            return -4.7, ('subscript_name' if '\\' in s else 'subscript')
        if s.startswith('\\'):
            return -2.35, 'subscript_name'
        if s.strip().isalpha() and len(s.strip()) > 2:
            return -1.03, ''
        return -2.79, ''
    if pending == 'subscript_name':
        if s in ('text', 'mathrm', 'rm', 'math'):
            return -0.54, 'subscript_format'
        return (-2.73 if s.lower() in GREEK
                else -0.54), ''
    if pending == 'subscript_format':
        return -0.54, 'subscript' if '{' in s else pending
    if pending == 'power':
        if s.strip() == '{':
            return -0.89, pending
        return (-0.99 if s == '2' else -0.96), ''
    if s and s[0].isdigit():
        small = ud.digit(s[0], 9) <= 2
        if spaced == 'greek':
            return -2.2, ''
        if b in ('single', 'function_word'):
            return (-1.1 if small else -0.7), ''
        if b == 'short':
            return -0.2, ''
        if tail.endswith(' ') and not tail.endswith('  ') and spaced == 'single':
            return (-1.5 if small else -0.4), ''
    if s == ' ' and b in ('single', 'greek'):
        return (-0.55 if b == 'greek' else -0.17), ''
    # In extracted PDF formulae, an index may itself carry its leading space.
    if s.startswith(' ') and spaced in ('single', 'greek'):
        word = s.strip()
        short_name = (len(word) <= 2 and word.isascii() and word.isalpha()
                      and word.lower() not in SHORT_FUNCTION_WORDS)
        if word and (short_name or len(word) == 1 and greek(word[0])):
            return (-1.09 if greek(word[0])
                    else -0.4), ''
    if b == 'greek' and s.isascii() and s.isalpha() and len(s) <= 2:
        return -1.09, ''
    return 0.0, ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail_bytes, pending = b'', ''
    else:
        _, tail_bytes, pending = carry
    s = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    tail = tail_bytes.decode('utf-8', 'replace')
    value, pending = predict(s, raw, tail, pending, tail_bytes)
    return (doc, (tail_bytes + raw)[-120:], pending), value

programs.haiku:
"""Layer-1 MLP neuron 2036 (down_proj component): a negative detector for subscripts and
superscripts written on a symbol, like z₁, x_{i}, C₂, x², CH₃ or <sub>i</sub>.

Activation is negative on the opening of a subscript or superscript attached to a symbol
(the "_" or "_{" after a variable) and on its first index token; it is strongest for
subscripts (about -3), weaker for superscripts (about -1) and for index digits written
in plain text after a symbol. The token "blank" after "target=\"_" is strongly positive."""
import string

READS: tuple[str, ...] = ()

LATIN = set(string.ascii_letters)
ENGLISH_WORDS = set("aAiIes")  # "a 2", "I 3": words, not symbols
OPERATORS = {"lim", "sum", "int", "max", "min", "inf", "sup", "arg", "log", "prod"}
SUB_DIGITS = set("₀₁₂₃₄₅₆₇₈₉")
SUP_DIGITS = set("²³")
DIGITS = set("0123456789")
SUB_OPENERS = {"_", "_{", "}_{", "_\\"}
SUP_OPENERS = {"^", "^{", "**"}


def is_symbol(s):
    """A single Latin letter (a variable or chemical symbol), with or without a leading space."""
    t = s.strip()
    return len(t) == 1 and t in LATIN


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    n = len(prefix.token_ids)
    same = lambda k: n > k and prefix.document_ids[-1 - k] == prefix.document_ids[-1]
    p = prefix.token_strings[-2] if same(1) else ""
    pp = prefix.token_strings[-3] if same(2) else ""
    after_symbol = is_symbol(p)
    if s == "blank" and p == "_":
        value = 8.9  # target="_blank"
    elif s in SUB_OPENERS and after_symbol:
        value = -2.9 if s != "_" else -1.0
    elif s in SUP_OPENERS and after_symbol:
        value = -1.0 if s != "^" else -0.5
    elif s in ("_{", "}_{") and p.strip() not in OPERATORS:
        value = -1.0  # a subscript on something other than a single letter
    elif s[:1] == "_" and len(s) > 1 and after_symbol:
        value = -1.3  # fused subscript name, as in C_i
    elif s and s[0] in SUB_DIGITS:
        value = -2.4 if (after_symbol or p in SUB_OPENERS) else -1.5
    elif s in SUP_DIGITS:
        value = -1.0 if (after_symbol or p.strip() in SUP_OPENERS) else -0.3
    elif s in ("{", "{\\") and p.strip() in SUB_OPENERS:
        value = -2.5  # braces that open a subscript
    elif s == "�" and after_symbol and p[0] != " ":
        value = -2.5  # first byte of a subscript character
    elif p in SUB_OPENERS and (is_symbol(pp) or pp == "}"):
        value = -2.7 if s in DIGITS or s in LATIN else -2.0  # first token inside a subscript
    elif p in SUP_OPENERS and is_symbol(pp):
        value = -1.0 if s in DIGITS else -0.7
    elif s in DIGITS and p == " " and is_symbol(pp):
        # "X 2": a spaced index after a symbol; not after the words a, I, i, e, s
        if pp.strip() in ENGLISH_WORDS:
            value = 0.0
        else:
            value = -2.0 if pp.strip().isupper() else -1.0
    elif s in DIGITS and is_symbol(p):
        value = -0.7
    elif s.startswith(">") and p == "sub" and pp == "<":
        value = -6.0  # HTML <sub>i</sub>
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Word-break marks and formatting at the beginning of a document.

Soft hyphens respond most strongly when alone after Latin letters, less when
merged with trailing letters. Nonbreaking hyphens and OCR's not-sign-as-hyphen
also respond more after letters than in numbers or formulas. Most other tokens
are near zero. At document openings there is a separate, usually negative
formatting response; repetitions of the opening token retain that response.
"""
import unicodedata

READS = ()

# Literal opening markers: terminal control, comments, markup, and separators.
OPENING_MARKERS = {
    '\r': -7.92,
    '\r\n': -1.54,
    '//\n': -9.58,
    '<!': -8.83,
    '^^^^': -2.31,
    '··': -0.86,
    '<|endoftext|>': -1.27,
}


def latin_letter(char):
    return bool(char) and 'LATIN' in unicodedata.name(char, '')


def opening_value(token):
    if token in OPENING_MARKERS:
        return OPENING_MARKERS[token]
    word = token.strip()
    if any('CYRILLIC' in unicodedata.name(c, '') for c in word):
        return 0.04 if token.startswith(' ') else 0.25
    if word.startswith('/*'):
        return -0.9
    if word in {'"', "'"}:
        return -0.95
    if not word:
        return -0.16
    punctuation = all(unicodedata.category(c)[0] in 'PS' for c in word)
    if punctuation:
        return -0.54 if '/' in word else -0.16
    if word.lower() in {'a', 'an', 'the'}:
        return -0.38
    if word.istitle() and all(latin_letter(c) for c in word):
        return -0.15
    return -0.05


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        first, opening, previous = token, True, ''
    else:
        _, first, opening, previous = carry
        opening = opening and token == first
    after_latin = latin_letter(previous[-1:])
    value = opening_value(token) if opening else 0.001

    if '\xad' in token:
        trailing = token.split('\xad')[-1]
        if len(trailing) > 1:
            value = 0.0
        elif trailing:
            value = 0.7
        elif token.startswith(' '):
            value = 1.0
        else:
            value = 1.8 if after_latin else 1.3
    elif '‑' in token:
        value = 0.35 if after_latin else 0.09
    elif token == '¬':
        value = 0.75 if after_latin else 0.08
    elif token == ' ¬':
        value = -0.04
    elif token == '\x00':
        value = 0.16
    elif token == '\u200c':
        value = 0.07
    elif not opening and token == '\xa0':
        value = 0.068
    return (doc, first, opening, token), value

"""Detect horizontal whitespace continued in a separate token.

A lone space after padding is the main response, stronger at line starts
and early in a document. Repeated tabs, nonbreaking-space padding,
and backtick markup after that padding have related responses.
Other tokens receive zero. State resets at each document boundary.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, prev, blank = 0, '', True
    else:
        _, pos, prev, blank = carry
    value = 0.0

    if s == ' ':
        n = len(prev) - len(prev.rstrip(' '))
        if n == 1:
            value = 0.30 + 0.80 * blank
        elif n > 1:
            value = (1.35 + 0.35 * blank + 0.15 * (min(n, 4) - 2)
                     - 0.35 * (n > 4) + 0.90 / (1 + pos / 20))
        elif pos == 0:
            value = 0.45
        if n and pos == 1:
            value += 0.40
    elif s == '\t':
        n = len(prev) - len(prev.rstrip('\t'))
        if n:
            value = (0.80 if n == 1 else 1.32 if n == 2 else 1.20)
            value -= (0.10 if n == 1 else 0.20) * blank
        elif prev.endswith(' ') and not prev.strip(' \t'):
            value = 0.47 if prev == ' ' else 1.15
    elif s == '\xa0' and prev and not prev.strip('\xa0'):
        # One more nonbreaking space after a three/seven-character chunk.
        if len(prev) in (3, 7):
            value = 1.40
    elif s == '``' and prev and not prev.strip('\xa0'):
        value = 1.0  # Backtick markup following nonbreaking-space padding.

    if '\n' in s:
        blank = not s.rsplit('\n', 1)[-1].strip(' \t\r\xa0')
    elif s.strip(' \t\r\xa0'):
        blank = False
    return (doc, pos + 1, s, blank), value

"""Year-like number prefixes and spacing/heading boundaries.

The third digit of a 19xx/20xx prefix gets a decade-dependent response,
stronger after a month name or a year-introducing preposition. A single
whitespace token continuing horizontal whitespace gets a positive response,
especially early in a document. Four-aligned nonbreaking-space indentation,
middle-dot leaders, and document-initial Title: headings are also recognized.
Everything else is approximately silent; state resets between documents.
"""
import calendar
import math
import re

READS = ()
MONTH = re.compile(r'\b(?:' + '|'.join(
    list(calendar.month_name)[1:] + list(calendar.month_abbr)[1:]
) + r')\b', re.I)
YEAR_PREP = re.compile(
    r'\b(in|since|from|until|during|by|of|year|between|around|circa)\s*$', re.I
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, previous, digits, tail, before, blanks = 0, '', '', '', '', 0
    else:
        _, pos, previous, digits, tail, before, blanks = carry
    s = prefix.token_strings[-1]
    value = 0.0
    horizontal = previous and not previous.strip(' \t')
    if s == ' ' and pos == 0:
        value = 1.39
    elif s == ' ' and horizontal:
        n = len(previous) - len(previous.rstrip(' '))
        base = 1.26 if n == 1 else 1.65 if n == 2 else 1.72
        if n == 4:
            base = 1.85
        elif n >= 5:
            base = max(1.1, 1.7 - 0.02 * n)
        boost = 0.25 if n == 1 else 0.65 if n == 2 else 0.9
        value = base + boost * math.exp(-pos / 35)
    elif s == '\t' and horizontal:
        value = min(1.3, 0.83 + 0.08 * previous.count('\t'))
    elif s == '\xa0' and blanks:
        remainder = (blanks + 1) % 4
        value = (1.8, -0.2, 0.5, 0.9)[remainder]
    elif s == '``' and previous == '\xa0':
        value = 1.0
    elif len(s) >= 2 and not s.strip('·'):
        value = 2.16
    elif s == ':' and previous.lower() == 'title' and pos < 4:
        value = 8.24 if pos == 1 and previous == 'Title' else 0.9
    elif pos == 0 and s == ' .':
        value = 2.5
    if len(s) == 1 and s in '0123456789':
        if not digits:
            before = tail
        if len(digits) == 2 and digits in ('19', '20'):
            decade = int(s)
            if digits == '19':
                value = max(-0.13, 0.15 * decade - 0.17)
            else:
                value = (0.65, 0.82, 0.41)[decade] if decade < 3 else -0.04
            if MONTH.search(before[-35:]) or YEAR_PREP.search(before):
                value += 0.22
            elif not before.rsplit('\n', 1)[-1].strip():
                value -= 0.12
        digits += s
    else:
        digits = ''
    blanks = blanks + len(s) if s and not s.strip('\xa0') else 0
    return (doc, pos + 1, s, digits, (tail + s)[-100:], before, blanks), float(value)

"""A local spelling feature for ch and related non-Latin letters.

The strongest regular response is negative on a lowercase fragment completing
split t+ch. Short o+ch fragments and some continuations of ch/sch are positive.
Case, token length, English frequency and doubled consonants modulate this.
Secondary rules cover Vietnamese diacritics and Cyrillic/Japanese letters.
These rules approximate spelling effects, not individual-word exceptions.
"""
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=40000)
def plain(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))

def vietnamese(s):
    return any('\u1ea0' <= c <= '\u1ef9' or c in 'ăđơưĂĐƠƯ' for c in s)

@lru_cache(maxsize=100000)
def response(s, previous):
    q, p = plain(s), plain(previous)
    w = q.strip()
    joined = bool(q and q[0].isalpha())
    before = anyascii(p[-1:]) if joined else ''
    if 'ч' in q:
        if q.startswith('ч') and before in ('t','n','l'):
            return -2.0
        return -0.05
    if 'チ' in s:
        return -0.25
    if 'ch' in q:
        at = q.index('ch')
        left = q[at-1:at] if at else before
        if vietnamese(s + previous) and w.startswith('ch'):
            return 0.5
        if q.startswith('ch') and left == 't' and len(w) <= 5:
            if s[0].islower():
                return -4.8
            return -1.0 if len(w) == 2 else 0.0
        if q.startswith('ch') and left in ('n','l'):
            if len(w) == 2:
                return -1.8
            return -0.8 if left == 'n' and s[0].islower() else -0.1
        if len(w) <= 3 and not s.startswith(' ') and left == 'o':
            return 1.3
        if w == 'ch':
            return 0.08 if joined else 0.3
        if 'tch' in w:
            rare = len(w) <= 6 and zipf_frequency(w, 'en') < 4
            return -0.45 if rare else -0.04
        if w.startswith(('che','chi','cho','chu')) and len(w) <= 8:
            doubled = any(a == b and a.isalpha() and a not in 'aeiouy'
                          for a, b in zip(w[2:], w[3:]))
            if doubled:
                return -1.1
            if zipf_frequency(w, 'en') < 4.7:
                return -0.1
        return -0.01
    if joined and p.endswith(('ch','χ','ч')):
        if vietnamese(s):
            return 3.0
        if p.endswith('tch'):
            return -0.4
        if p.endswith(('sch','χ')):
            if w.startswith(('l','r')):
                if previous.strip()[:1].isupper():
                    return 1.4
                return 0.65 if len(w) <= 3 else 0.0
            return 0.2
        if w.startswith('in'):
            return -0.7
        if w.startswith('a'):
            return 0.6
        if w.startswith('r') and len(w) <= 3:
            return 1.4
        if w.startswith('i'):
            return 0.3
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, s), float(response(s, previous))

"""A local spelling detector, strongest on dose/dosage/doping words.

Smaller responses occur in expos-, diagnos-, and doz- spellings and in
phrases headed by 'do'. Split words are recognized using the previous
fragment, including transliterated d/o/s/z spellings. This is not a general
medical-topic detector: most text is assigned zero. Selected d-/do-
continuations, such as d+ancing and do+xygen, receive negative values.
"""
from anyascii import anyascii
from functools import lru_cache
from unicodedata import name, combining
from wordfreq import zipf_frequency

READS = ()
DO_FORMS = {'do', 'does', 'did', 'done', 'doing'}


@lru_cache(maxsize=8192)
def spelling(text):
    alphabetic = all(
        ch.isascii() or combining(ch) or any(
            script in name(ch, '') for script in ('LATIN', 'CYRILLIC', 'GREEK')
        ) for ch in text
    )
    return (anyascii(text) if alphabetic else text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    text = spelling(raw)
    word = text.lstrip()
    prev = previous.strip()
    prev_raw = '' if carry is None or carry[0] != doc else carry[2]
    value = 0.0

    if word == 'dose':
        value = 7.1
    elif word == 'doses':
        value = 5.3
    elif word.startswith('dosage'):
        value = 3.2
    elif word.startswith('overdose'):
        value = 4.6
    elif word in ('dop', 'dope', 'doped', 'doping'):
        value = 3.8 if word.startswith('doping') else 2.0
    elif word.startswith('expos'):
        value = 0.8 if word.startswith('exposed') else 1.8
    elif word.startswith('diagnos'):
        value = 0.85 if word.startswith('diagnosed') else 0.6
    elif word.startswith('dozen'):
        value = 1.8
    elif word.startswith('dough'):
        value = -0.75
    elif word == 'dos':
        value = 3.2 if raw.strip().isupper() else 0.0
        # Distinguish an English word beginning dos- from Spanish/Portuguese
        # 'dos', using the language frequency of its left-hand context.
        en = zipf_frequency(prev, 'en')
        other = max(zipf_frequency(prev, 'es'), zipf_frequency(prev, 'pt'))
        if prev_raw.isascii() and en > other + 0.7:
            value = 3.6

    if text and not text[0].isspace():
        if previous.endswith('d'):
            # A lone d is a much stronger cue than d buried in a fragment.
            strength = 1.0 if prev.strip('-/') == 'd' else 0.0
            if prev_raw.lower().endswith('под'):
                strength = 0.5
            if word == 'oz':
                value = 12.0 * strength
            elif word in ('ose', 'oses'):
                value = 11.0 * strength
            elif word == 'osis':
                value = 7.5 * strength
            elif word in ('os', 'osz'):
                value = (6.5 if raw.isupper() else 1.8) * strength
            elif word.startswith('oped'):
                value = 6.2 * strength
            elif word in ('ope', 'oping'):
                value = 4.7 * strength
            elif word.startswith(('op', 'ode', 'oh')):
                value = 2.4 * strength
            elif word.startswith('ou'):
                value = 0.8 * strength
            elif word.startswith('ext'):
                value = -3.2 * strength
            elif word.startswith('ancing'):
                value = -1.7 * strength
            if prev.endswith('overd') and word.startswith('oses'):
                value = 10.0
        if previous.endswith('do'):
            if word == 'ze':
                value = 4.5
            elif word in ('x', 'xy', 'xygen'):
                value = -3.7
            elif word in ('on', 'h', 'ge', 's', 'kh'):
                value = 3.5 if word == 'kh' else 2.0
        if previous.endswith('dos') and word in ('ing', 'ages', 'is'):
            value = 6.0
        if previous.endswith('ex') and word in ('pose', 'posed', 'posing', 'posure'):
            value = 2.5
        if previous.endswith('dis') and word.startswith('pos'):
            value = 1.8
        if previous.endswith('des') and word.startswith('ens'):
            value = 0.75
        if previous.endswith('agn') and word.startswith(('osed', 'oses')):
            value = 1.9
    elif prev in DO_FORMS:
        if word == 'nothing':
            value = 2.7
        elif word == 'something':
            value = 1.5
        elif word == 'to':
            value = 1.2 if prev in ('done', 'does') else 2.7
    elif word == 'of' and prev in ('dose', 'died', 'doctor'):
        value = 2.5 if prev == 'doctor' else 1.3
    return (doc, text, raw.strip()), value

"""A source-boundary heuristic, not a full parser.

Opening function bodies receive large positive values; class openings receive
smaller ones. Semicolons are usually negative, especially inside parentheses
or after C# accessors. Statement endings with escaped newlines are positive.
The last 600 characters provide context and reset at document boundaries.
"""
import re
READS = ()
CONTROL = {'if', 'for', 'while', 'switch', 'catch', 'with', 'match',
           'foreach', 'synchronized', 'elif', 'unless'}


def signature(context):
    """Find the name before the last complete, balanced argument list."""
    end = context.rfind(')')
    if end < 0:
        return ''
    tail = context[end + 1:].strip()
    if tail and not re.fullmatch(
        r'(?:(?:->|throws)\s*[\w<>\[\],.*&:\x27?() ]+'
        r'|(?:const|override|noexcept|final|error|[A-Z]\w*(?:\.\w+)*)\s*)', tail):
        return ''
    depth = 1
    start = end - 1
    while start >= 0 and depth:
        depth += (context[start] == ')') - (context[start] == '(')
        start -= 1
    if depth:
        return ''
    lead = context[:start + 1]
    lead = re.sub(r'<[^\n]*>\s*$', '', lead)
    match = re.search(r'([\w:~]+)\s*$', lead)
    if not match:
        recent = re.split(r'[;{}]', context)[-1]
        return 'function' if re.search(r'\bfunc\s+.*\(', recent) else ''
    name = match.group(1)
    if name in CONTROL:
        return 'control'
    if re.search(r'\bdef\s+\w+\s*$', lead):
        return 'python_empty' if not context[start + 2:end].strip() else 'python'
    if re.search(r'\bnew\s+[\w.<>]+\s*$', lead):
        return 'control'
    return 'function'


def predict(text, before):
    bare = text.strip()
    newline = '\n' in text or '\r' in text or text.endswith('\\')
    context = before.replace('\\n', '\n').replace('\\r', '\n').replace('`', '')
    if ('{' in text and '}' not in text) or (':' in text and newline):
        punctuation = '{' if '{' in text else ':'
        part = text.split(punctuation, 1)[0].replace('`', '')
        header = (context + part)[-500:]
        kind = signature(header)
        if punctuation == ':':
            if not kind.startswith('python'):
                return 0.0
            if bare.startswith(':'):
                return 6.2
            return 1.7 if kind == 'python_empty' else 4.2
        if not re.fullmatch(r'[\s`()]*\{[\s\\]*', text):
            kind = ''
        recent = re.split(r'[;{}]', header)[-1]
        if not kind and re.search(
            r'\b(?:fn|function)\s+\w+(?:<[^{};]*>)?\s*\('
            r'|\bfunc\s+(?:\([^)]*\)\s*)?\w+\s*\(', recent):
            kind = 'function'
        tail = re.split(r'[\n;{}]', header)[-1]
        if kind == 'control' or re.search(
            r'\b(if|for|while|else|try|finally|do|switch|match)\b', tail):
            return 0.1 if newline else 0.0
        if kind == 'function' or kind.startswith('python'):
            if ')' in part:
                return 2.0
            if not context.rsplit('\n', 1)[-1].strip():
                return 5.8
            return 4.5 if newline else 4.0
        if re.search(
            r'\b(class|struct|interface|enum|namespace|impl|trait)'
            r'\s+[\w<>:, ]*$', tail):
            return 1.5 if newline else 0.5
        return 0.1 if newline else -0.05
    if ';' in text:
        if re.search(r'&(?:#\w*|[A-Za-z]+)$', before):
            return 0.0
        if text.endswith('\\'):
            return 2.2 if bare.startswith(';') else 1.2
        statement = re.split(r'[;{}\n]', context)[-1].strip()
        statement = re.sub(r'^\d+\s+', '', statement)
        code = bool(re.match(
            r'(?:return|break|continue|throw|using|import|package|delete|cout|cerr)\b'
            r'|(?:(?:public|private|protected|static|final|const|unsigned|signed)\s+)*'
            r'(?:int|float|double|char|bool|boolean|string|long|short|byte|var|let|auto|String)\b'
            r'|[A-Z]\w*(?:<[^>]*>|\[\])?\s+\w+\b'
            r'|[\w.]+(?:\[[^]]*\])?\s*(?:[+*/-]?=(?!=)|\+\+|--)', statement))
        if newline:
            if code:
                return 0.6
            return -0.45 if bare.startswith(';') else 0.07
        if bare == ';':
            if re.search(r'\b(get|set|init)\s*$', before):
                return -4.0
            if before.rfind('(') > before.rfind(')'):
                return -1.75
            return -0.6 if code or text[0].isspace() else -1.1
        return -0.25 if code else -0.45
    if bare == 'import':
        return 0.45 if text[0].isspace() else 0.06
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    return (doc, (before + text)[-600:]), predict(text, before)

