        value = -5.4
    elif word in ('帮我', '幫我'):
        value = -3.0
    elif word in ('帮你', '幫你'):
        value = -2.3
    elif word in ('帮忙', '幫忙'):
        value = -1.9
    elif '帮助' in word:
        value = -0.7
    elif '幫助' in word:
        value = -0.3
    elif word == '帮扶':
        value = -0.9
    elif word == '忙':
        if previous.endswith(('帮', '幫', '百', '一个')):
            value = -4.0
        elif previous.endswith(('很', '最', '匆匆', '忙')):
            value = -1.2
        else:
            value = -2.5
    elif word == 'bang':
        value = -1.0
    elif word == 'Bang':
        value = -0.4 if text.startswith(' ') else -1.4
    elif word == 'ang' and previous.lower().endswith('b'):
        value = -0.9
    elif word == '知道':
        value = -1.0
    elif word == '银行':
        value = -1.0
    elif word == '解读':
        value = 1.5
    elif word == '阅读' and previous.endswith('相关'):
